insert into public.exercises (slug, name, muscle_group, equipment, mechanic, level, data) values
('ab-wheel-rollout', 'Ab Wheel Rollout', 'abs', 'other', 'compound', 'advanced', '{"slug":"ab-wheel-rollout","name":"Ab Wheel Rollout","aliases":["Ab Roller","Rollout"],"muscle_group":"abs","secondary":["shoulders","lower-back"],"equipment":"other","mechanic":"compound","level":"advanced","summary":"A demanding rollout that trains the abs to resist extension of the spine. Start with a short range of motion.","setup":["Kneel on a mat and hold the ab wheel under your shoulders.","Tuck the pelvis slightly and round the upper back a little.","Brace the abs and squeeze the glutes."],"execution":["Roll the wheel forward slowly, keeping the hips and ribs in line.","Go only as far as you can keep the lower back from arching.","Pull the wheel back by contracting the abs, not by dropping the hips first.","Return to the start position and repeat."],"cues":["Ribs down, glutes tight","Short range first","Slow in and out"],"mistakes":["Arching the lower back: shorten the range and keep the pelvis tucked.","Dropping the hips first on the way back: lead with the abs.","Going too far too soon: increase range gradually over weeks.","Using the wheel against a wall for beginners if the movement is too hard."],"default_sets":3,"default_reps":"6-10","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=rqiTPdK1c_I","title":"Ab Wheel- How to PROPERLY Use an Ab Wheel | MIND PUMP","author":"Mind Pump TV","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=_BHKT60P6bc","title":"Strengthening the core: Ab Wheel","author":"UCLA Health","checked":"2026-10-23"}]}'::jsonb),
('arnold-press', 'Arnold Press', 'shoulders', 'dumbbell', 'compound', 'intermediate', '{"slug":"arnold-press","name":"Arnold Press","aliases":["Rotational Dumbbell Press"],"muscle_group":"shoulders","secondary":["triceps"],"equipment":"dumbbell","mechanic":"compound","level":"intermediate","summary":"A dumbbell press variation with a rotation that adds extra time under tension for the front and side shoulders.","setup":["Sit on a bench with back support holding dumbbells at chest height, palms facing you.","Elbows are in front of the body, upper arms close together.","Brace the core and keep the ribs down.","Use a moderate weight since rotating is demanding."],"execution":["Press the dumbbells up while rotating the palms to face forward.","Finish with the arms nearly straight overhead, palms forward.","Lower while rotating the palms back toward you.","Return to the start with control."],"cues":["Rotate as you press","Smooth, controlled turn","Stay tall"],"mistakes":["Using momentum to rotate: go lighter and slow the tempo.","Arching the back: keep the back on the pad and ribs down.","Rushing the rotation: make it continuous across the full movement.","Shrugging: keep shoulders down."],"default_sets":3,"default_reps":"8-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=ris9tKqMwgU","title":"Stop F*cking Up The Arnold Press (PROPER FORM!)","author":"ATHLEAN-X™","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=P75JfZFBYC8","title":"How To Arnold Press in 4 Minutes - Form Secrets, Mistakes to Avoid","author":"MuscleWiki","checked":"2026-10-23"}]}'::jsonb),
('assisted-pull-up', 'Assisted Pull-Up Machine', 'lats', 'machine', 'compound', 'beginner', '{"slug":"assisted-pull-up","name":"Assisted Pull-Up Machine","aliases":["Machine Assisted Pull-Up","Assisted Chin-Up"],"muscle_group":"lats","secondary":["biceps","back","forearms"],"equipment":"machine","mechanic":"compound","level":"beginner","summary":"A machine with a counterweight that takes part of your body weight so you can practice the pull-up pattern with full range. Useful for building toward unassisted pull-ups.","setup":["Set the assistance weight so you can finish your reps with good form; more weight means more help.","Step onto the platform or kneel on the pad and grab the handles.","Let the arms straighten and set the shoulder blades down before the first rep."],"execution":["Pull the elbows down toward your ribs.","Raise until your chin passes the handles while the chest stays up.","Pause briefly at the top.","Lower slowly until the arms are fully straight, then repeat."],"cues":["Elbows to ribs","Do not shrug","Slow on the way down"],"mistakes":["Bouncing off the bottom: control the descent and keep tension in the shoulders.","Choosing too much assistance forever: reduce the assistance gradually as reps become easy.","Pulling mostly with the arms: lead with the shoulder blades and elbows.","Leaning back and turning it into a row: keep the torso mostly upright."],"default_sets":3,"default_reps":"8-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=THSFzwAqYgk","title":"How to use the Assisted Pull Up Machine","author":"McMaster Marauders","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=lGCl8kVa6-c","title":"Beginner Guide To The Assisted Pull Up Machine!","author":"Laci Renee ","checked":"2026-10-23"}]}'::jsonb),
('back-extension', 'Back Extension', 'lower-back', 'other', 'compound', 'beginner', '{"slug":"back-extension","name":"Back Extension","aliases":["Hyperextension","45-Degree Back Extension"],"muscle_group":"lower-back","secondary":["glutes","hamstrings"],"equipment":"other","mechanic":"compound","level":"beginner","summary":"A bodyweight hip-hinge exercise on a hyperextension bench that strengthens the lower back, glutes and hamstrings.","setup":["Adjust the pad so it sits just below your hip bones and your ankles are secured under the rollers.","Cross your arms over your chest or hold them lightly behind your head.","Start with your body in a straight line from head to heels."],"execution":["Hinge forward at the hips, lowering your torso with a neutral spine until you feel a stretch in your hamstrings.","Keep your neck in line with your spine.","Squeeze your glutes and raise your torso back up until your body forms a straight line.","Stop at a straight line instead of hyperextending your lower back.","Repeat with control."],"cues":["Hinge at the hips","Squeeze the glutes","Stop at a straight line"],"mistakes":["Hyperextending at the top: finish when your body is in a straight line.","Rounding the spine at the bottom: stop the descent where you can keep a neutral back.","Using momentum: slow down and use a controlled tempo.","Pad too high so the hips cannot hinge: set it just below the hips."],"default_sets":3,"default_reps":"10-15","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=gLT-WLH84B4","title":"Back Extension (Hyperextension) - Proper Form & Technique [4K]","author":"Steev","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=qtjJUWCnDyE","title":"Hyperextensions (Back Extensions) - Core / Back Exercise - Bodybuilding.com","author":"Bodybuilding.com","checked":"2026-10-23"}]}'::jsonb),
('band-pull-apart', 'Band Pull-Apart', 'rear-delts', 'band', 'isolation', 'beginner', '{"slug":"band-pull-apart","name":"Band Pull-Apart","aliases":["Resistance Band Pull Apart","Banded Pull Apart"],"muscle_group":"rear-delts","secondary":["traps","back"],"equipment":"band","mechanic":"isolation","level":"beginner","summary":"A simple band exercise that trains the rear shoulders and upper back. It is useful as a warm-up or posture-friendly accessory at home.","setup":["Hold a light resistance band in front of you at chest height with arms straight.","Use an overhand grip about shoulder-width apart, with enough tension to keep the band taut.","Stand tall with ribs down, glutes tight and shoulders relaxed."],"execution":["Pull the band apart by moving your hands out to the sides, keeping your arms straight.","Squeeze your shoulder blades together as the band reaches your chest.","Pause for a moment, then return slowly to the start.","Keep your neck relaxed and wrists neutral."],"cues":["Spread the band wide","Squeeze shoulder blades","Ribs down","Slow return"],"mistakes":["Shrugging the shoulders: keep them down and away from your ears.","Arching the lower back: tighten the abs and glutes.","Using a band that is too strong: choose one that lets you move smoothly through the full range.","Letting the band snap back: control the return with your back muscles."],"default_sets":3,"default_reps":"12-20","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=stwYTTPXubo","title":"How To Do Banded Pull-Aparts","author":"Tangelo - Seattle Chiropractor + Rehab","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=3OYSIWaJJk4","title":"The Band Pull-Apart for a Stronger Back","author":"Men''s Health","checked":"2026-10-23"}]}'::jsonb),
('barbell-back-squat', 'Barbell Back Squat', 'quads', 'barbell', 'compound', 'intermediate', '{"slug":"barbell-back-squat","name":"Barbell Back Squat","aliases":["Back Squat","Squat"],"muscle_group":"quads","secondary":["glutes","hamstrings","abs","lower-back"],"equipment":"barbell","mechanic":"compound","level":"intermediate","summary":"A foundational lower-body lift that loads the quads, glutes and trunk through a full squat pattern. It builds leg strength and muscle and carries over to most other leg work.","setup":["Set the bar in a rack at about upper-chest height and step under it so it rests across your upper back (on the rear delts for a low bar, on the traps for a high bar).","Grip the bar just outside your shoulders, pull your shoulder blades together and unrack it with a straight back.","Take two or three small steps back and set your feet about shoulder width with toes turned out slightly.","Take a big breath into your belly and brace your trunk before each rep."],"execution":["Start the descent by pushing your hips back and bending your knees together, keeping your whole foot on the floor.","Keep your chest up and your knees tracking in line with your toes as you lower to at least thigh parallel, or as deep as you can control with a neutral spine.","Pause briefly at the bottom without relaxing your brace.","Drive through the whole foot and stand up, keeping your hips and chest rising at the same rate.","Exhale at the top, re-brace and repeat; re-rack by walking forward until the bar touches the hooks."],"cues":["Big breath, tight trunk","Knees out over toes","Whole foot on the floor","Chest and hips rise together"],"mistakes":["Knees caving inward: think about spreading the floor apart with your feet and push the knees out in line with the toes.","Heels lifting or weight shifting to the toes: keep pressure through the midfoot and heel and widen the stance or lower the weight if needed.","Hips shooting up first so the torso folds forward: slow the ascent, keep the chest up and reduce the load.","Cutting depth short with heavy weight: use a load you can take to a consistent depth, ideally set safety pins in the rack."],"default_sets":4,"default_reps":"5-8","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=8PMjqgR8Wa8","title":"How to Barbell Back Squat | A Tutorial for Beginners","author":"Barbell Rehab","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=irA7MTz96ho","title":"BEGINNER''S GUIDE TO BACK SQUATS","author":"Kelly Matthews","checked":"2026-10-23"}]}'::jsonb),
('barbell-bench-press', 'Barbell Bench Press', 'chest', 'barbell', 'compound', 'intermediate', '{"slug":"barbell-bench-press","name":"Barbell Bench Press","aliases":["Flat Bench Press","Bench Press"],"muscle_group":"chest","secondary":["triceps","shoulders"],"equipment":"barbell","mechanic":"compound","level":"intermediate","summary":"The classic horizontal press for the chest, front delts and triceps. A staple for building upper-body pressing strength and muscle.","setup":["Lie on the bench with eyes under the bar, feet flat on the floor under your knees.","Pull your shoulder blades back and down and keep them pinned to the bench; keep a small natural arch in the upper back.","Grip the bar slightly wider than shoulder width with the bar low in the palm and wrists stacked over forearms.","Unrack with straight arms and settle the bar over the shoulders. Set the safety arms or use a spotter."],"execution":["Take a breath, brace your abs and lower the bar under control to the lower chest/sternum area, elbows about 45-70 degrees from the torso.","Touch the chest lightly without bouncing.","Press the bar back up and slightly toward the rack in a smooth path until the arms are straight.","Rack the bar only when the set is finished and the arms are locked out."],"cues":["Shoulder blades back and down","Feet planted, push the floor away","Bend the bar in your hands, elbows tucked not flared","Control down, drive up"],"mistakes":["Bouncing the bar off the chest: lower with control and pause briefly on the chest.","Elbows flared to 90 degrees: tuck them to roughly 45-70 degrees to protect the shoulders.","Hips lifting off the bench: keep glutes down and drive through the feet instead.","Wrists bent back: stack the bar over the forearm with a firm grip."],"default_sets":3,"default_reps":"5-10","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=4Y2ZdHCOXok","title":"How to PROPERLY Bench Press for Growth (5 Easy Steps)","author":"Jeremy Ethier","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=vcBig73ojpE","title":"How To Get A Huge Bench Press with Perfect Technique","author":"Jeff Nippard","checked":"2026-10-23"}]}'::jsonb),
('barbell-bent-over-row', 'Barbell Bent-Over Row', 'back', 'barbell', 'compound', 'intermediate', '{"slug":"barbell-bent-over-row","name":"Barbell Bent-Over Row","aliases":["Bent-Over Row","Barbell Row"],"muscle_group":"back","secondary":["lats","biceps","rear-delts","lower-back","traps"],"equipment":"barbell","mechanic":"compound","level":"intermediate","summary":"A heavy hip-hinged row that builds the upper and mid back, lats and rear delts while training trunk strength.","setup":["Stand with feet hip width and the bar over mid-foot.","Hinge at the hips until the torso is roughly 30-45 degrees above horizontal and grip the bar just outside the knees.","Stand the bar up, brace the abs and keep the spine neutral with knees slightly bent."],"execution":["Pull the bar toward the lower ribs or upper stomach by driving the elbows back.","Squeeze the shoulder blades together at the top without standing up.","Lower the bar under control until the arms are straight.","Keep the torso angle the same on every rep."],"cues":["Hips back, spine long","Elbows to the ceiling","Torso angle stays still"],"mistakes":["Rounding the lower back: lighten the load and brace harder before each rep.","Standing up to heave the bar: keep the torso angle fixed and reduce the weight.","Pulling to the chest with flared elbows: pull to the lower ribs with elbows around 45 degrees.","Shortening the range: let the arms fully extend between reps."],"default_sets":4,"default_reps":"6-10","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=kBWAon7ItDw","title":"How To PROPERLY Barbell Row For A Bigger Back (Stop Making These Mistakes!)","author":"Jeremy Ethier","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=ML1L5ytxLMY","title":"Barbell Row — Form, Mistakes, and Variations","author":"BarBend","checked":"2026-10-23"}]}'::jsonb),
('barbell-curl', 'Barbell Curl', 'biceps', 'barbell', 'isolation', 'beginner', '{"slug":"barbell-curl","name":"Barbell Curl","aliases":["Standing Barbell Curl","Straight Bar Curl"],"muscle_group":"biceps","secondary":["forearms"],"equipment":"barbell","mechanic":"isolation","level":"beginner","summary":"A classic standing curl that loads both arms evenly and lets you use heavier weights than most biceps exercises. Builds the biceps and the muscles that bend the elbow.","setup":["Stand tall with feet hip-width apart and take an underhand grip on the bar, hands about shoulder-width apart.","Let the bar hang at thigh level with elbows beside your ribs and a soft knee bend.","Brace your abs and pull the shoulder blades slightly down and back."],"execution":["Curl the bar up by bending only at the elbows, keeping the upper arms nearly still.","Continue until the forearms are close to vertical and the biceps are fully shortened, without lifting the shoulders.","Pause briefly, then lower the bar over about 2-3 seconds to full arm extension.","Exhale as you curl up and inhale on the way down."],"cues":["Elbows pinned to your sides","Wrists straight, not bent back","Lower slower than you lift"],"mistakes":["Swinging the torso to move the bar: lower the weight and keep your glutes and abs tight.","Elbows drifting far forward: keep them beside the ribs so the biceps, not the shoulders, do the work.","Cutting the bottom short: lower until the arms are almost straight on every rep.","Bending the wrists back under load: keep the wrists neutral in line with the forearms."],"default_sets":3,"default_reps":"8-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=SSDJzQIds0E","title":"Get Strong at Barbell Curls!","author":"Alex Leonidas","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=llqu4IFYSQw","title":"Barbell Bicep Curl Workout (GET BIGGER ARMS!)","author":"Fit Father Project - Fitness For Busy Fathers","checked":"2026-10-23"}]}'::jsonb),
('barbell-front-squat', 'Barbell Front Squat', 'quads', 'barbell', 'compound', 'advanced', '{"slug":"barbell-front-squat","name":"Barbell Front Squat","aliases":["Front Squat"],"muscle_group":"quads","secondary":["glutes","abs","lower-back"],"equipment":"barbell","mechanic":"compound","level":"advanced","summary":"A squat variation with the bar held on the front of the shoulders, which keeps the torso upright and puts a strong emphasis on the quads and trunk. It also demands good upper-back strength and mobility.","setup":["Set the bar in a rack at about mid-chest height.","Step up to the bar and rest it on the front of your shoulders, close to your throat but not pressing on it, using a clean grip or crossed-arm grip.","Lift your elbows so your upper arms are about parallel to the floor, then unrack and step back.","Set your feet about shoulder width with toes turned out slightly and brace your trunk."],"execution":["Take a breath, brace, and sit straight down while your knees track forward over your toes.","Keep your elbows high so the bar stays on your shoulders and your chest stays tall.","Lower to at least thigh parallel, or as deep as you can control without your torso collapsing.","Drive up through the whole foot, keeping the elbows up the entire time.","Re-rack once the set is done by walking forward until the bar touches the hooks."],"cues":["Elbows high","Chest tall","Sit straight down between the hips","Whole foot on the floor"],"mistakes":["Elbows dropping and the torso folding forward: lighten the load, lift the elbows and think about pushing the chest up.","Bar rolling off the shoulders because of a poor grip: use the crossed-arm grip or work on wrist and lat mobility, or switch to straps for a bodybuilder-style hold.","Heels lifting: widen the stance a little, or wear flat shoes with a firm sole.","Rounding the upper back at the bottom: reduce depth and the weight until you can hold position."],"default_sets":3,"default_reps":"5-8","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=npVgCT7NznU","title":"Front Squat 101: Beginner''s Guide","author":"MuscleWiki","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=Q4REDQdplnM","title":"Barbell Front Squat Tutorial","author":"Fox Body Fitness","checked":"2026-10-23"}]}'::jsonb),
('barbell-hip-thrust', 'Barbell Hip Thrust', 'glutes', 'barbell', 'compound', 'intermediate', '{"slug":"barbell-hip-thrust","name":"Barbell Hip Thrust","aliases":["Hip Thrust"],"muscle_group":"glutes","secondary":["hamstrings","quads","abs"],"equipment":"barbell","mechanic":"compound","level":"intermediate","summary":"A glute-focused lift where the upper back is supported on a bench and you drive a loaded barbell upward with your hips. It lets you load the glutes heavily in the shortened position.","setup":["Sit on the floor with your upper back against the side of a stable bench and roll the bar over your legs to your hips, using a pad if needed.","Place your feet about hip width apart, shins about vertical at the top, and the bench edge just below your shoulder blades.","Hold the bar steady with both hands.","Tuck your chin slightly and brace your trunk."],"execution":["Drive through your feet and lift your hips until your torso is roughly parallel to the floor.","Squeeze your glutes at the top with your shins close to vertical.","Keep your ribs down and chin tucked so you do not overarch your lower back.","Lower your hips under control until the bar is near the floor, without resting.","Repeat, then roll the bar off when finished."],"cues":["Chin tucked, ribs down","Push through the feet","Squeeze the glutes at the top","Shins vertical at lockout"],"mistakes":["Overarching the lower back at the top: tuck the ribs down and stop when the hips and torso are in line.","Feet too far forward or too close: adjust so your shins are about vertical at lockout.","Pushing through the toes: keep the whole foot, especially the heel, planted.","Bar rolling or hurting the hips: use a thick pad and keep the bar centered."],"default_sets":3,"default_reps":"8-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=pBH7pKHn-dI","title":"How to Perform Barbell Hip Thrusts | Glutes Exercise Tutorial","author":"Buff Dudes Workouts","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=4hYRM_60BD4","title":"HOW TO BARBELL HIP THRUST | Coach Kelly Cues","author":"Kelly Matthews","checked":"2026-10-23"}]}'::jsonb),
('barbell-overhead-press', 'Barbell Overhead Press', 'shoulders', 'barbell', 'compound', 'intermediate', '{"slug":"barbell-overhead-press","name":"Barbell Overhead Press","aliases":["Standing Overhead Press","Military Press","Shoulder Press"],"muscle_group":"shoulders","secondary":["triceps","abs"],"equipment":"barbell","mechanic":"compound","level":"intermediate","summary":"A standing barbell press that builds shoulder and triceps strength while training core stability.","setup":["Set the bar at upper chest height in a rack and grip just outside shoulder width.","Unrack with the bar resting on the front shoulders, elbows slightly in front of the bar.","Stand with feet about hip width, squeeze glutes and brace abs.","Keep the forearms vertical."],"execution":["Press the bar straight up, moving your head slightly back then forward through as the bar passes the forehead.","Lock out with the bar over the middle of the foot, ribs down.","Lower under control back to the shoulders.","Repeat without leaning back."],"cues":["Glutes tight, ribs down","Bar over mid-foot at lockout","Head through"],"mistakes":["Excessive lean-back and lower-back arch: squeeze glutes and brace the abs.","Bar drifting forward: keep a vertical forearm and move the head out of the way.","Flared ribs: keep them stacked over the pelvis.","Pressing from a bouncing start: reset on the shoulders each rep."],"default_sets":3,"default_reps":"5-8","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=nNMR9fRGRjQ","title":"How to Press: Proper Overhead Press Form (Step-by-Step Tutorial)","author":"Barbell Logic","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=-5MmFTKLC-0","title":"How To Perfect The Overhead Press","author":"PureGym","checked":"2026-10-23"}]}'::jsonb),
('barbell-pendlay-row', 'Pendlay Row', 'back', 'barbell', 'compound', 'advanced', '{"slug":"barbell-pendlay-row","name":"Pendlay Row","aliases":["Barbell Pendlay Row","Dead-Stop Row"],"muscle_group":"back","secondary":["lats","traps","rear-delts","biceps","lower-back"],"equipment":"barbell","mechanic":"compound","level":"advanced","summary":"A strict barbell row where the bar returns to the floor after every rep and the torso stays parallel to the ground, emphasizing explosive pulling from a dead stop.","setup":["Stand with the bar over mid-foot and hinge until the torso is roughly parallel to the floor.","Grip the bar slightly wider than shoulder width with an overhand grip.","Set a flat back, tight lats and braced abs with the bar resting on the floor."],"execution":["Pull the bar explosively to the lower chest or upper stomach.","Keep the torso parallel to the floor, with no hip or chest lift.","Lower the bar under control back to the floor and reset.","Re-brace before each rep."],"cues":["Dead stop each rep","Torso stays parallel","Elbows drive back and up"],"mistakes":["Raising the torso to heave the weight: lighten the load and keep the angle.","Losing the flat back at the floor: reset and brace before every pull.","Bouncing the bar off the floor: pause briefly and re-set tension.","Using an underhand grip with heavy weight: use an overhand grip."],"default_sets":4,"default_reps":"5-8","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=axoeDmW0oAY","title":"How To Build a Thick Back With Perfect Rowing Technique (Pendlay Row/ Helms Row)","author":"Jeff Nippard","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=2xJ7FG7_T7c","title":"How To: Pendlay Row","author":"CJ McFarland","checked":"2026-10-23"}]}'::jsonb),
('barbell-reverse-wrist-curl', 'Barbell Reverse Wrist Curl', 'forearms', 'barbell', 'isolation', 'beginner', '{"slug":"barbell-reverse-wrist-curl","name":"Barbell Reverse Wrist Curl","aliases":["Reverse Wrist Curl","Wrist Extension"],"muscle_group":"forearms","secondary":[],"equipment":"barbell","mechanic":"isolation","level":"beginner","summary":"A seated wrist movement with an overhand grip that trains the forearm extensors on the top of the forearm. Use light loads.","setup":["Sit holding a light barbell with an overhand grip, hands shoulder-width apart.","Rest your forearms on your thighs or a bench with the wrists hanging off the edge.","Keep your forearms still and relaxed."],"execution":["Lower the bar by letting the wrists bend toward the floor under control.","Extend the wrists to lift the bar as high as you can.","Pause briefly at the top.","Lower slowly and repeat."],"cues":["Light weight","Only the wrists move","Slow tempo"],"mistakes":["Using too much weight and losing control: pick a load that lets you move through the full range.","Lifting the forearms off the support: keep them anchored.","Bouncing at the bottom: pause and lift smoothly.","Rushing the reps: keep a steady 2-second lift and lower."],"default_sets":3,"default_reps":"12-15","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=FW7URAaC-vE","title":"How To: Reverse Seated Wrist Curl","author":"ScottHermanFitness","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=2WP49wiI2vg","title":"Reverse Wrist Curl","author":"Scott Hagnas","checked":"2026-10-23"}]}'::jsonb),
('barbell-shrug', 'Barbell Shrug', 'traps', 'barbell', 'isolation', 'beginner', '{"slug":"barbell-shrug","name":"Barbell Shrug","aliases":["Shrug"],"muscle_group":"traps","secondary":["forearms","shoulders"],"equipment":"barbell","mechanic":"isolation","level":"beginner","summary":"A vertical shrug with a barbell that directly loads the upper trapezius and trains grip.","setup":["Stand with feet hip width holding the barbell in front of the thighs with an overhand grip just outside the hips.","Stand tall with the chest up, shoulders relaxed and arms straight.","Brace the abs and keep the head neutral."],"execution":["Lift the shoulders straight up toward the ears.","Pause for a second at the top.","Lower slowly until the shoulders are fully relaxed down.","Keep the arms straight throughout."],"cues":["Shoulders to ears","Straight up, straight down","Pause at the top"],"mistakes":["Rolling the shoulders: shrug straight up and down.","Bending the elbows to help: keep the arms straight and use lighter weight.","Bouncing with the legs: stand still and control the tempo.","Going too heavy with a short range: use a load that allows a full lift and pause."],"default_sets":3,"default_reps":"10-15","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=q4x4syK-eXM","title":"Barbell Shrugs (How To, Grips, Coaching Tips)","author":"Horton Barbell","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=larn3Asl6oM","title":"How To Do Barbell Shrugs","author":"PureGym","checked":"2026-10-23"}]}'::jsonb),
('barbell-upright-row', 'Barbell Upright Row', 'shoulders', 'barbell', 'compound', 'intermediate', '{"slug":"barbell-upright-row","name":"Barbell Upright Row","aliases":["Upright Row"],"muscle_group":"shoulders","secondary":["traps","biceps"],"equipment":"barbell","mechanic":"compound","level":"intermediate","summary":"A vertical pull that trains the side delts and upper traps; use a comfortable grip width and range to keep the shoulders happy.","setup":["Stand tall holding a barbell with an overhand grip about shoulder width or slightly wider.","Let the bar hang in front of the thighs with arms straight.","Brace the core and keep the ribs down.","Keep the bar close to the body."],"execution":["Lead with the elbows, pulling the bar up along the torso.","Raise to about chest height; do not go higher if the shoulders feel pinched.","Pause briefly, then lower under control.","Keep the torso upright."],"cues":["Elbows lead","Bar close to the body","Chest height is enough"],"mistakes":["Pulling too high with elbows far above the hands: stop at about chest height.","Using body momentum: reduce load and stay still.","Grip too narrow causing wrist or shoulder discomfort: widen the grip.","Shrugging excessively: lead with the elbows, not the traps."],"default_sets":3,"default_reps":"8-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=93BUvCE92As","title":"How to Upright Row PROPERLY While Avoiding Pain! Fix Your Upright Barbell Row Form NOW!","author":"Colossus Fitness","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=cVD0X9Yb_hw","title":"How to perform a barbell upright row","author":"Human Kinetics","checked":"2026-10-23"}]}'::jsonb),
('barbell-wrist-curl', 'Barbell Wrist Curl', 'forearms', 'barbell', 'isolation', 'beginner', '{"slug":"barbell-wrist-curl","name":"Barbell Wrist Curl","aliases":["Seated Wrist Curl","Forearm Curl"],"muscle_group":"forearms","secondary":[],"equipment":"barbell","mechanic":"isolation","level":"beginner","summary":"A seated curl that moves only the wrists to train the forearm flexors, which help your grip strength.","setup":["Sit on a bench holding a barbell with an underhand grip, hands shoulder-width apart.","Rest your forearms on your thighs or the bench with the wrists hanging past the edge.","Choose a light load so you can control the full range."],"execution":["Let the bar roll down toward your fingertips, keeping the forearms still.","Curl the hands back up by flexing the wrists as far as you can.","Squeeze briefly at the top.","Lower slowly and repeat for all reps."],"cues":["Only the wrists move","Slow and controlled","Light weight, high reps"],"mistakes":["Lifting the forearms off the bench: keep them supported and flat.","Using too much weight and bouncing: lower the load and slow down.","Cutting the range short: use the full stretch and squeeze each rep.","Gripping too hard at the fingertips: let the bar roll down only as far as you can control."],"default_sets":3,"default_reps":"12-15","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=qMtmHwaCmYI","title":"How To: Seated Wrist Curl","author":"ScottHermanFitness","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=3VLTzIrnb5g","title":"How To Do Wrist Curls","author":"PureGym","checked":"2026-10-23"}]}'::jsonb),
('bench-dip', 'Bench Dip', 'triceps', 'bodyweight', 'compound', 'beginner', '{"slug":"bench-dip","name":"Bench Dip","aliases":["Triceps Bench Dip"],"muscle_group":"triceps","secondary":["chest","shoulders"],"equipment":"bodyweight","mechanic":"compound","level":"beginner","summary":"A bodyweight triceps exercise using a bench behind you; the feet position changes how hard it is.","setup":["Sit on the edge of a bench and place your hands next to your hips, fingers pointing forward.","Slide your hips off the bench with arms straight and shoulders down.","Bend the knees for an easier version or extend the legs for harder.","Keep the body close to the bench."],"execution":["Bend the elbows to lower the hips toward the floor, elbows pointing back.","Lower until the upper arms are around parallel to the floor; no deeper if the shoulders feel strained.","Press back up until the arms are straight.","Keep the shoulders down away from the ears throughout."],"cues":["Elbows back, not out","Shoulders down","Stay close to the bench"],"mistakes":["Dropping too low so shoulders roll forward: limit depth to about 90 degrees at the elbows.","Hips drifting far from the bench: keep them close.","Flaring the elbows: keep them pointing straight back.","Shrugging up: keep the shoulders depressed."],"default_sets":3,"default_reps":"8-15","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=zcHaDdf4sEM","title":"How to do a triceps dip on a bench","author":"Rehab My Patient","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=Fq7Oy-t3APQ","title":"Bench Dips - Tricep Exercises for Men","author":"ThatLeanLook","checked":"2026-10-23"}]}'::jsonb),
('bent-over-dumbbell-rear-delt-fly', 'Bent-Over Dumbbell Rear Delt Fly', 'rear-delts', 'dumbbell', 'isolation', 'beginner', '{"slug":"bent-over-dumbbell-rear-delt-fly","name":"Bent-Over Dumbbell Rear Delt Fly","aliases":["Rear Delt Fly","Bent-Over Reverse Fly"],"muscle_group":"rear-delts","secondary":["back","traps"],"equipment":"dumbbell","mechanic":"isolation","level":"beginner","summary":"An isolation exercise for the rear delts and upper back performed while hinged forward.","setup":["Hold light dumbbells and hinge at the hips with a flat back until the torso is near parallel to the floor.","Let the arms hang below the shoulders, palms facing each other.","Keep a slight bend in the elbows.","Brace the core and keep the neck neutral."],"execution":["Raise the arms out to the sides in an arc until about shoulder height.","Lead with the elbows and squeeze the shoulder blades lightly.","Pause, then lower slowly.","Keep the torso still."],"cues":["Lead with the elbows","Flat back","Pinch lightly at the top"],"mistakes":["Rounding the back: hinge from the hips and brace the abs.","Using momentum: use lighter weights and slow the tempo.","Shrugging into the traps: keep shoulders down.","Raising too high: stop at around shoulder height."],"default_sets":3,"default_reps":"12-20","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=LsT-bR_zxLo","title":"The PERFECT Dumbbell Rear Delt Fly (DO THIS!)","author":"Andrew Kwong (DeltaBolic)","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=JeSlI2s4XfM","title":"Bent Over Dumbbell Reverse Fly (Rear Delt Workout!)","author":"V Shred","checked":"2026-10-23"}]}'::jsonb),
('bicycle-crunch', 'Bicycle Crunch', 'abs', 'bodyweight', 'isolation', 'beginner', '{"slug":"bicycle-crunch","name":"Bicycle Crunch","aliases":["Bicycle Crunches"],"muscle_group":"abs","secondary":[],"equipment":"bodyweight","mechanic":"isolation","level":"beginner","summary":"A rotational crunch that trains the abs and obliques.","setup":["Lie on your back with knees bent.","Place your fingertips lightly behind your head.","Press your lower back toward the floor and brace the abs."],"execution":["Lift your head and shoulders and bring your legs up.","Rotate your torso to bring one elbow toward the opposite knee while extending the other leg.","Switch sides in a smooth pedaling motion.","Keep your elbows wide and avoid pulling on your neck."],"cues":["Rotate the ribs","Lower back down","Slow and steady"],"mistakes":["Pulling on the neck: keep hands light and lead with the chest.","Rushing the reps: slow down and rotate fully.","Lower back arching: lower the legs less or keep the feet higher.","Only moving the elbows: turn the shoulders toward the knee."],"default_sets":3,"default_reps":"12-20 per side","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=eqg47ZuGZXQ","title":"Strengthening the core: Bicycle Crunch","author":"UCLA Health","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=wpRI3xBhJmo","title":"How To Do A Bicycle Crunch | The Right Way | Well+Good","author":"Well+Good","checked":"2026-10-23"}]}'::jsonb),
('bird-dog', 'Bird Dog', 'lower-back', 'bodyweight', 'isolation', 'beginner', '{"slug":"bird-dog","name":"Bird Dog","aliases":["Quadruped Arm and Leg Raise"],"muscle_group":"lower-back","secondary":["abs","glutes"],"equipment":"bodyweight","mechanic":"isolation","level":"beginner","summary":"A floor exercise on all fours that trains trunk stability and coordination, working the back muscles, glutes and abs together.","setup":["Start on hands and knees with the wrists under the shoulders and the knees under the hips.","Keep the spine neutral and the neck in line.","Brace the abs lightly."],"execution":["Reach one arm forward and the opposite leg back at the same time.","Keep the hips and shoulders level and avoid twisting.","Pause for a moment, then return to the start under control.","Repeat on the other side."],"cues":["Long spine","Hips level","Slow and controlled"],"mistakes":["Arching the lower back: lift the limbs only as high as you can keep the spine neutral.","Rotating the hips: keep both hips facing the floor.","Rushing: move slowly and pause at the end.","Holding the breath: breathe steadily."],"default_sets":3,"default_reps":"8-10 per side","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=xEDnlOxeJH4","title":"How to Do the Bird Dog Exercise: A Guide from Physical Therapists","author":"Hinge Health","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=QABW99qPiNM","title":"Bird Dog Exercise | Improve Your Core and Balance","author":"Muscle & Motion","checked":"2026-10-23"}]}'::jsonb),
('bodyweight-calf-raise', 'Bodyweight Calf Raise', 'calves', 'bodyweight', 'isolation', 'beginner', '{"slug":"bodyweight-calf-raise","name":"Bodyweight Calf Raise","aliases":["Standing Calf Raise","Single-Leg Calf Raise"],"muscle_group":"calves","secondary":[],"equipment":"bodyweight","mechanic":"isolation","level":"beginner","summary":"A simple calf exercise done on the floor or the edge of a step, on both legs or one leg.","setup":["Stand with the balls of your feet on the edge of a stair or sturdy step, heels hanging off.","Hold a wall or railing for balance.","For single leg, cross one foot behind the other ankle."],"execution":["Lower the heels below the step for a stretch.","Rise as high as you can on your toes.","Pause at the top and squeeze.","Lower slowly."],"cues":["Full stretch, full squeeze","Slow lowering","Tall posture"],"mistakes":["Bouncing: use a slow tempo.","Rolling to the outer edge of the foot: press through the big toe.","Short range: go from deep stretch to full height.","Bending the knees: keep legs straight."],"default_sets":3,"default_reps":"12-20","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=ZSa8XCt6VLQ","title":"SINGLE LEG CALF RAISE OVER STEP","author":"Your Rehab Physio","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=qPd73snQfUs","title":"Single-Leg Calf Raise (HSS)","author":"Hospital for Special Surgery","checked":"2026-10-23"}]}'::jsonb),
('bodyweight-reverse-lunge', 'Bodyweight Reverse Lunge', 'quads', 'bodyweight', 'compound', 'beginner', '{"slug":"bodyweight-reverse-lunge","name":"Bodyweight Reverse Lunge","aliases":["Reverse Lunge","Backward Lunge"],"muscle_group":"quads","secondary":["glutes","hamstrings"],"equipment":"bodyweight","mechanic":"compound","level":"beginner","summary":"A single-leg dominant lunge that steps backward, which is usually easier on the knees and balance than a forward lunge.","setup":["Stand tall with feet hip width apart, hands on your hips or in front of you.","Brace your abs and look straight ahead.","Hold a wall or chair back lightly if you need balance."],"execution":["Step one foot back about a long stride and land on the ball of the foot.","Lower straight down until both knees are bent to about 90 degrees, with the back knee just above the floor.","Keep your torso upright and the front heel flat.","Push through the front foot to return to standing, then repeat on the other side or finish the set on one leg."],"cues":["Step back, drop straight down","Front heel heavy","Tall chest"],"mistakes":["Front knee collapsing inward: push it out in line with the middle toes.","Taking too short a step so the front knee travels far forward: step back farther.","Leaning forward at the waist: keep the chest up and the abs braced.","Bouncing off the back knee: lower under control and touch lightly or stop just above the floor."],"default_sets":3,"default_reps":"8-12 per leg","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=xrPteyQLGAo","title":"How To Reverse Lunge","author":"PureGym","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=C_P3Q-PssvY","title":"How To Do A Reverse Lunge | The Right Way | Well+Good","author":"Well+Good","checked":"2026-10-23"}]}'::jsonb),
('bodyweight-squat', 'Bodyweight Squat', 'quads', 'bodyweight', 'compound', 'beginner', '{"slug":"bodyweight-squat","name":"Bodyweight Squat","aliases":["Air Squat","Squat"],"muscle_group":"quads","secondary":["glutes","hamstrings","abs"],"equipment":"bodyweight","mechanic":"compound","level":"beginner","summary":"A foundational squat with no equipment that trains the thighs and glutes and builds the movement pattern for loaded squats.","setup":["Stand with feet about shoulder width apart, toes turned out slightly.","Hold your arms out in front or clasp your hands at chest height for balance.","Brace your abs and keep your chest tall."],"execution":["Push your hips back and bend your knees at the same time.","Lower until your thighs are about parallel to the floor, or as deep as you can with a flat back and heels down.","Keep your knees tracking in line with your toes.","Press through the whole foot to stand up and squeeze your glutes at the top."],"cues":["Sit between your hips","Knees over toes","Whole foot on the floor"],"mistakes":["Heels lifting off the floor: widen the stance slightly or hold the arms forward for balance.","Knees caving in: push them out in line with the toes.","Rounding the lower back at the bottom: reduce depth until you can stay neutral.","Leaning too far forward: keep the chest up and look straight ahead."],"default_sets":3,"default_reps":"12-20","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=AIZ8q1qruKw","title":"How to Perform a PERFECT Squat","author":"Squat University","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=l83R5PblSMA","title":"Leg exercise - How to bodyweight squat","author":"PureGym","checked":"2026-10-23"}]}'::jsonb),
('bulgarian-split-squat', 'Bulgarian Split Squat', 'quads', 'dumbbell', 'compound', 'intermediate', '{"slug":"bulgarian-split-squat","name":"Bulgarian Split Squat","aliases":["Rear-Foot Elevated Split Squat","BSS"],"muscle_group":"quads","secondary":["glutes","hamstrings","abs"],"equipment":"dumbbell","mechanic":"compound","level":"intermediate","summary":"A single-leg squat with the rear foot elevated on a bench. It heavily loads the front leg''s quads and glutes and challenges balance and hip mobility.","setup":["Stand about two feet in front of a bench and place the top of one foot on it behind you.","Hold a dumbbell in each hand at your sides.","Set your front foot far enough forward that your front shin stays roughly vertical at the bottom.","Brace your trunk with your torso slightly leaning forward."],"execution":["Lower your hips straight down by bending the front knee.","Keep your front knee tracking in line with your toes and your front foot flat.","Descend until your front thigh is about parallel or as deep as you can control.","Drive through the front foot to stand back up.","Complete all reps on one leg, then switch."],"cues":["Drop straight down","Front foot flat","Slight forward lean, brace hard"],"mistakes":["Front foot too close to the bench so the knee runs over the toes and the heel lifts: step the front foot farther forward.","Pushing off the back foot: keep the back leg as a support and drive with the front.","Torso collapsing or swaying: slow down, lighten the load, and brace.","Knee caving in: push it out in line with the toes."],"default_sets":3,"default_reps":"8-12 per leg","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=-4LVK1crLSw","title":"The ULTIMATE Bulgarian Split Squat Tutorial","author":"Squat University","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=hiLF_pF3EJM","title":"Stop F*cking Up Bulgarian Split Squats (PROPER FORM!)","author":"ATHLEAN-X™","checked":"2026-10-23"}]}'::jsonb),
('burpee', 'Burpee', 'quads', 'bodyweight', 'compound', 'intermediate', '{"slug":"burpee","name":"Burpee","aliases":["Squat Thrust with Jump"],"muscle_group":"quads","secondary":["chest","shoulders","abs","triceps"],"equipment":"bodyweight","mechanic":"compound","level":"intermediate","summary":"A full-body conditioning move that links a squat, plank and jump to raise the heart rate.","setup":["Stand with feet shoulder width apart on a non-slip surface.","Clear space around you and use a mat if your hands slide.","Brace your abs."],"execution":["Squat down and place your hands on the floor in front of you.","Jump or step your feet back into a straight-body plank.","Optionally lower your chest to the floor for a push-up.","Jump or step your feet back toward your hands.","Jump up explosively with arms overhead and land softly."],"cues":["Hands down, feet back","Straight plank","Land soft"],"mistakes":["Hips sagging in the plank: brace the abs and squeeze glutes.","Rounded back as you stand: keep the chest up when jumping in.","Stiff landing: bend the knees to absorb it.","Too fast, sloppy reps: step instead of jump, or skip the push-up."],"default_sets":3,"default_reps":"8-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=qLBImHhCXSw","title":"How To Do A Burpee | The Right Way | Well+Good","author":"Well+Good","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=G2hv_NYhM-A","title":"How To Do Burpees With Proper Form","author":"BuiltLean®","checked":"2026-10-23"}]}'::jsonb),
('cable-crossover', 'Cable Crossover', 'chest', 'cable', 'isolation', 'intermediate', '{"slug":"cable-crossover","name":"Cable Crossover","aliases":["Cable Fly","Standing Cable Fly"],"muscle_group":"chest","secondary":["shoulders"],"equipment":"cable","mechanic":"isolation","level":"intermediate","summary":"A standing cable fly that keeps constant tension on the chest as the handles are brought together in front of the body.","setup":["Set both pulleys high and attach single handles.","Grab a handle in each hand and step forward into a staggered stance.","Lean slightly forward with a neutral spine and a soft bend in the elbows.","Start with arms open to the sides, hands about shoulder level or slightly lower."],"execution":["Brace your core and sweep the handles down and together in a wide arc in front of the chest.","Squeeze the chest at the point where the hands meet.","Reverse the arc slowly, letting the arms open until you feel a chest stretch.","Keep the elbow angle fixed and shoulders down throughout."],"cues":["Hug in an arc","Chest squeeze at the end","Control the return"],"mistakes":["Swinging the torso with momentum: lower the weight and stay steady.","Letting the elbows bend more as it gets hard (pressing): keep the angle fixed.","Overstretching with the shoulders pulled far back: stop where you feel the chest, not the front of the shoulder.","Weight stack slamming between reps: do not rest the stack; keep tension."],"default_sets":3,"default_reps":"10-15","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=aoP0s_MjN-g","title":"Cable Crossover - Chest Exercise - Bodybuilding.com","author":"Bodybuilding.com","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=taI4XduLpTk","title":"How to Do Cable Crossovers","author":"LIVESTRONG","checked":"2026-10-23"}]}'::jsonb),
('cable-crunch', 'Cable Crunch', 'abs', 'cable', 'isolation', 'intermediate', '{"slug":"cable-crunch","name":"Cable Crunch","aliases":["Kneeling Cable Crunch","Rope Crunch"],"muscle_group":"abs","secondary":[],"equipment":"cable","mechanic":"isolation","level":"intermediate","summary":"A weighted crunch with a high cable and rope, which lets you progressively load the abs.","setup":["Attach a rope to a high pulley and kneel a short distance from the stack.","Hold the rope at both sides of your head, elbows pointing down.","Sit the hips back slightly and keep the hips still."],"execution":["Curl the spine by pulling the ribs toward the pelvis, bringing the elbows toward the thighs.","Hold briefly at the bottom with the abs fully contracted.","Return slowly to the upright position.","Keep the hips fixed and let the abs move the weight, not the arms."],"cues":["Ribs to pelvis","Hips stay still","Slow return"],"mistakes":["Pulling with the arms: keep the hands fixed beside the head and move through the trunk.","Moving the hips back and forth: keep them still and lighten the load.","Using too much weight: pick a load you can control for the full range.","Bending only at the hips: curl the spine, not just fold at the hips."],"default_sets":3,"default_reps":"10-15","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=QR3vANGukK8","title":"Cable Crunches: The CORRECT Way To Do Them (Most People Are Wrong)","author":"Leo Fanner","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=aBd6T01PBqw","title":"How to PROPERLY Perform A Cable Crunch to Shape Your Abs (Kneeling Cable Abdominal Crunch)","author":"Colossus Fitness","checked":"2026-10-23"}]}'::jsonb),
('cable-curl', 'Cable Curl', 'biceps', 'cable', 'isolation', 'beginner', '{"slug":"cable-curl","name":"Cable Curl","aliases":["Standing Cable Biceps Curl"],"muscle_group":"biceps","secondary":["forearms"],"equipment":"cable","mechanic":"isolation","level":"beginner","summary":"A curl using a low cable pulley that keeps constant tension on the biceps through the whole range of motion.","setup":["Attach a straight bar or rope to the low pulley and select a light to moderate weight.","Stand facing the stack, feet hip-width apart, and take the bar with an underhand grip.","Step back slightly so there is tension in the cable, elbows at your sides."],"execution":["Curl the handle up by bending only at the elbows.","Squeeze at the top without leaning back.","Lower slowly until the arms are almost straight, keeping tension on the cable.","Stay upright and do not let the stack rest between reps."],"cues":["Constant tension","Elbows pinned to ribs","Stand tall"],"mistakes":["Leaning back to lift the weight: reduce the load and brace the core.","Elbows drifting forward: keep them at your sides.","Letting the stack drop on the way down: lower the handle under control.","Shrugging the shoulders: keep them down and relaxed."],"default_sets":3,"default_reps":"10-15","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=2MUEL4nL6hA","title":"How to PROPERLY Cable Bicep Curl For Bigger Biceps (EASY FIX)","author":"Colossus Fitness","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=NFzTWp2qpiE","title":"How To Do Cable Bicep Curls - Full Video Tutorial and Step-by-Step Guide","author":"Fit Father Project - Fitness For Busy Fathers","checked":"2026-10-23"}]}'::jsonb),
('cable-pull-through', 'Cable Pull-Through', 'glutes', 'cable', 'compound', 'beginner', '{"slug":"cable-pull-through","name":"Cable Pull-Through","aliases":["Pull Through"],"muscle_group":"glutes","secondary":["hamstrings","lower-back"],"equipment":"cable","mechanic":"compound","level":"beginner","summary":"A cable hip-hinge exercise that teaches and trains hip extension for the glutes and hamstrings, with constant tension and low spinal load.","setup":["Attach a rope to a low pulley.","Stand facing away from the machine, straddle the cable and hold the rope between your legs with both hands.","Walk forward until the cable has tension and set your feet about shoulder width apart.","Keep a soft knee bend and a flat back."],"execution":["Push your hips straight back, letting the rope pass between your legs.","Keep your back flat and arms straight as you hinge until you feel a hamstring stretch.","Drive your hips forward by squeezing your glutes.","Stand tall at the top without leaning back.","Repeat with control."],"cues":["Hips back, then hips through","Flat back, soft knees","Squeeze the glutes at the top"],"mistakes":["Squatting instead of hinging: send the hips back with a fixed knee angle.","Pulling with the arms: keep arms straight and move at the hips.","Leaning back at the top: finish standing tall.","Rounding the back: reduce the weight and brace your trunk."],"default_sets":3,"default_reps":"10-15","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=OkcryKUZTZs","title":"CABLE PULL THROUGH Exercise for Amazing GLUTES & Hamstrings","author":"Criticalbench","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=_u4gJO0ELhE","title":"Cable Pull-Through","author":"Onnit Academy","checked":"2026-10-23"}]}'::jsonb),
('chest-dip', 'Chest Dip', 'chest', 'bodyweight', 'compound', 'intermediate', '{"slug":"chest-dip","name":"Chest Dip","aliases":["Parallel Bar Dip","Dips"],"muscle_group":"chest","secondary":["triceps","shoulders"],"equipment":"bodyweight","mechanic":"compound","level":"intermediate","summary":"A bodyweight press on parallel bars; a forward torso lean emphasizes the lower chest while still working the triceps and shoulders.","setup":["Grip the parallel bars and lift yourself to straight arms, shoulders pulled down away from the ears.","Lean the torso forward slightly and bend the knees, crossing the ankles behind you.","Keep elbows slightly flared and the chest open.","Make sure shoulders are warmed up; dips load the shoulder joint heavily."],"execution":["Lower under control while keeping the forward lean, until the upper arms are about parallel to the floor or you feel a comfortable chest stretch.","Keep the shoulders down and do not let them roll forward.","Press back up until the arms are straight.","Repeat without swinging."],"cues":["Chest forward, shoulders down","Smooth lowering","Press through the palms"],"mistakes":["Dropping too deep with shoulders collapsing forward: stop around parallel or where the shoulders feel stable.","Bouncing out of the bottom: lower slowly and pause.","Shrugging toward the ears: keep shoulders depressed.","Swinging the legs: keep the body still and brace the core."],"default_sets":3,"default_reps":"6-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=yN6Q1UI_xkE","title":"How To Do Dips For A Bigger Chest and Shoulders (Fix Mistakes!)","author":"Jeff Nippard","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=BNi3UmLyV8Q","title":"How to Build a Bigger Chest: The PERFECT Dip (Full Guide)","author":"SaturnoMovement","checked":"2026-10-23"}]}'::jsonb),
('chest-supported-dumbbell-row', 'Chest-Supported Dumbbell Row', 'back', 'dumbbell', 'compound', 'beginner', '{"slug":"chest-supported-dumbbell-row","name":"Chest-Supported Dumbbell Row","aliases":["Incline Bench Dumbbell Row","Seal Row (Dumbbell)"],"muscle_group":"back","secondary":["lats","rear-delts","biceps","traps"],"equipment":"dumbbell","mechanic":"compound","level":"beginner","summary":"A row done lying chest-down on an incline bench, which removes lower-back and momentum demands so the upper back does the work.","setup":["Set an adjustable bench to about 30-45 degrees.","Lie chest-down with your chest and head against the pad and feet planted on the floor.","Take a dumbbell in each hand and let the arms hang straight with the shoulders set."],"execution":["Row both dumbbells toward your hips, leading with the elbows.","Squeeze the shoulder blades together at the top.","Lower under control until the arms are straight.","Keep the chest on the pad throughout."],"cues":["Elbows to the hips","Chest stays glued to the pad","Pause and squeeze"],"mistakes":["Lifting the chest off the pad: lower the weight and stay supported.","Shrugging up: keep the shoulders down and away from the ears.","Pulling the elbows too high and wide: row at about 45 degrees to the torso for the back.","Dropping the weights: lower slowly through the full stretch."],"default_sets":3,"default_reps":"8-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=Nx0TzjgsI-0","title":"How To Do An Incline Dumbbell Row","author":"PureGym","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=zng2aKf1PPs","title":"Dumbbell Chest-Supported Row","author":"Testosterone Nation","checked":"2026-10-23"}]}'::jsonb),
('chin-up', 'Chin-Up', 'lats', 'bodyweight', 'compound', 'intermediate', '{"slug":"chin-up","name":"Chin-Up","aliases":["Underhand Pull-Up","Supinated Pull-Up"],"muscle_group":"lats","secondary":["biceps","back","forearms"],"equipment":"bodyweight","mechanic":"compound","level":"intermediate","summary":"A pull-up variation with an underhand grip that shifts more work to the biceps while still training the lats and upper back. Usually a little easier than the overhand pull-up.","setup":["Grab the bar with an underhand (palms facing you) grip about shoulder width.","Hang with arms straight, ribs down and legs slightly in front.","Set the shoulder blades down and back before you pull."],"execution":["Pull the elbows down and forward toward your hips.","Continue until your chin is above the bar without craning the neck.","Pause briefly at the top with the chest toward the bar.","Lower slowly to a full hang with straight arms."],"cues":["Chest up to the bar","Elbows down, not back","Control the way down"],"mistakes":["Using only the arms: start each rep by pulling the shoulder blades down.","Swinging or kicking the legs: squeeze the glutes and abs and reduce speed.","Stopping short of a full hang: lower until the elbows are straight on every rep.","Grip too narrow for the wrists or elbows: use shoulder width or slightly wider."],"default_sets":3,"default_reps":"6-10","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=qV7vOUcUfD4","title":"How To Do CHIN-UPS: Grip, Weighted Chin-Ups, Programming, & Fixing Common Errors","author":"Barbell Logic","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=nILkwSyrE3Y","title":"CHIN-UP | COACHING THE PROPER CHIN-UP","author":"KILO Strength Society Education","checked":"2026-10-23"}]}'::jsonb),
('close-grip-bench-press', 'Close-Grip Bench Press', 'triceps', 'barbell', 'compound', 'intermediate', '{"slug":"close-grip-bench-press","name":"Close-Grip Bench Press","aliases":["CGBP","Close Grip Barbell Bench Press"],"muscle_group":"triceps","secondary":["chest","shoulders"],"equipment":"barbell","mechanic":"compound","level":"intermediate","summary":"A bench press with a narrower grip that shifts more of the load to the triceps while still working the chest.","setup":["Lie on a flat bench with eyes under the bar and feet planted.","Grip the bar about shoulder width; not so narrow that the wrists bend.","Pull shoulder blades back and down.","Unrack with straight arms; set safety arms or use a spotter."],"execution":["Lower the bar under control to the lower chest, elbows close to the body.","Touch lightly without bouncing.","Press the bar up until the arms are straight.","Keep wrists straight over forearms throughout."],"cues":["Elbows tucked","Shoulder-width grip","Press the bar up and slightly back"],"mistakes":["Grip too narrow causing wrist pain: use about shoulder width.","Elbows flaring: keep them close to the ribs.","Bouncing the bar: pause and control it.","Hips rising: keep the glutes on the bench."],"default_sets":3,"default_reps":"6-10","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=AELjbx9CedA","title":"Close Grip Bench Press Basics","author":"The Physio Fix","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=DzA2xZhDGeo","title":"How To Do A Close Grip Barbell Bench Press","author":"PureGym","checked":"2026-10-23"}]}'::jsonb),
('close-grip-lat-pulldown', 'Close-Grip Lat Pulldown', 'lats', 'cable', 'compound', 'beginner', '{"slug":"close-grip-lat-pulldown","name":"Close-Grip Lat Pulldown","aliases":["Neutral-Grip Lat Pulldown","V-Bar Pulldown"],"muscle_group":"lats","secondary":["biceps","back","rear-delts"],"equipment":"cable","mechanic":"compound","level":"beginner","summary":"A pulldown with a narrow neutral-grip (V) handle that allows a longer range of motion and a comfortable wrist and shoulder position. Trains the lats, mid back and biceps.","setup":["Attach a V-handle or neutral-grip bar and secure your thighs under the pad.","Grab the handle with palms facing each other and sit tall.","Lean back slightly and let the arms extend with the shoulders set."],"execution":["Pull the shoulder blades down to start.","Drive the elbows down and back along your sides.","Bring the handle to the upper chest or sternum.","Return slowly until the arms are straight."],"cues":["Elbows tight by the ribs","Lead with the elbows","Full stretch at the top"],"mistakes":["Rocking the torso to move the weight: lower the load and keep the lean fixed.","Shortening the stretch at the top: let the arms fully extend each rep.","Pulling with the biceps only: think elbows down, not hands down.","Letting the shoulders roll forward: keep the chest up."],"default_sets":3,"default_reps":"8-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=mUoo2l-p8Hw","title":"Close Grip Lat Pulldown | Proper Technique + Form Tips","author":"Vivian Ngo","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=IjoFCmLX7z0","title":"How To Do A Close Grip Lat Pulldown","author":"PureGym","checked":"2026-10-23"}]}'::jsonb),
('concentration-curl', 'Concentration Curl', 'biceps', 'dumbbell', 'isolation', 'beginner', '{"slug":"concentration-curl","name":"Concentration Curl","aliases":["Seated Dumbbell Concentration Curl"],"muscle_group":"biceps","secondary":[],"equipment":"dumbbell","mechanic":"isolation","level":"beginner","summary":"A seated single-arm curl with the elbow braced against the inner thigh. The fixed position makes cheating hard and focuses tension on the biceps.","setup":["Sit on a bench with feet wide and take a dumbbell in one hand.","Rest the back of the upper arm against the inside of your thigh with the arm hanging straight.","Place your free hand on the other thigh and lean slightly forward with a flat back."],"execution":["Curl the dumbbell toward your shoulder, keeping the upper arm braced on the thigh.","Squeeze the biceps at the top, forearm near vertical.","Lower slowly until the arm is nearly straight.","Finish all reps, then switch arms."],"cues":["Elbow stays against the thigh","Curl up in a smooth arc","Slow lowering"],"mistakes":["Swinging the torso: keep the chest still and use a lighter dumbbell.","Letting the elbow slide off the thigh: reset the position so the upper arm stays fixed.","Cutting the range of motion short: lower to a nearly straight arm each rep.","Rounding the back heavily: sit tall with a flat back and tilt only from the hips."],"default_sets":3,"default_reps":"10-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=oPGBZHIxusU","title":"How To Do a Concentration Curl - [THE PERFECT DB CURL]","author":"Fit Father Project - Fitness For Busy Fathers","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=Jvj2wV0vOYU","title":"How To: Dumbbell Concentration Curl","author":"ScottHermanFitness","checked":"2026-10-23"}]}'::jsonb),
('conventional-deadlift', 'Conventional Deadlift', 'hamstrings', 'barbell', 'compound', 'intermediate', '{"slug":"conventional-deadlift","name":"Conventional Deadlift","aliases":["Deadlift","Barbell Deadlift"],"muscle_group":"hamstrings","secondary":["glutes","lower-back","traps","forearms","quads"],"equipment":"barbell","mechanic":"compound","level":"intermediate","summary":"A full-body pull from the floor that trains the glutes, hamstrings, back and grip. It is one of the best exercises for overall strength when done with good technique.","setup":["Stand with your feet about hip width apart and the bar over your midfoot, close to your shins.","Hinge and bend your knees to grip the bar just outside your legs with straight arms.","Pull the slack out of the bar, set your lats by pulling the bar into your body, and bring your chest up.","Take a big breath, brace your trunk and keep a neutral spine."],"execution":["Push the floor away with your legs while keeping the bar close to your body.","Keep your back angle the same until the bar passes your knees.","Drive your hips forward and stand tall, squeezing your glutes at the top without leaning back.","Lower by pushing your hips back first, then bending the knees once the bar passes them.","Reset your setup and breath before every rep."],"cues":["Push the floor away","Bar scrapes the legs","Lats tight, chest up","Hips and chest rise together"],"mistakes":["Rounding the lower back: lower the weight and focus on bracing and setting the lats before pulling.","Bar drifting forward away from the body: start with the bar over the midfoot and keep your lats engaged.","Hips shooting up first: think about pushing the floor away rather than pulling with the back.","Leaning back or hyperextending at lockout: finish tall by squeezing the glutes, not by arching."],"default_sets":3,"default_reps":"3-6","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=VL5Ab0T07e4","title":"Build A Bigger Deadlift With Perfect Technique (Conventional Form)","author":"Jeff Nippard","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=9popgktCkyA","title":"Barbell Deadlift Technique Explained","author":"Physical Therapy First","checked":"2026-10-23"}]}'::jsonb),
('crunch', 'Crunch', 'abs', 'bodyweight', 'isolation', 'beginner', '{"slug":"crunch","name":"Crunch","aliases":["Floor Crunch","Abdominal Crunch"],"muscle_group":"abs","secondary":[],"equipment":"bodyweight","mechanic":"isolation","level":"beginner","summary":"A basic floor exercise that flexes the spine to train the rectus abdominis through a short range of motion.","setup":["Lie on your back with the knees bent and feet flat on the floor.","Place the fingertips lightly behind the head or cross the arms on your chest.","Press the lower back gently toward the floor and brace the abs."],"execution":["Curl the head, neck and shoulder blades off the floor using your abs.","Pause briefly at the top with the ribs drawn toward the pelvis.","Lower back down slowly under control.","Exhale as you curl up and inhale as you lower."],"cues":["Ribs toward the hips","Short controlled curl","Do not pull on the neck"],"mistakes":["Pulling on the neck with the hands: keep the fingertips light and look up at the ceiling.","Using momentum: slow down and control both directions.","Sitting up too high: lift only the shoulder blades off the floor.","Holding the breath: exhale on the way up."],"default_sets":3,"default_reps":"12-20","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=okqQVQireEo","title":"PT TIPS: How to perform an Abdominal Crunch","author":"Vast Fitness Academy","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=NGRKFMKhF8s","title":"How To: Floor Crunch","author":"ScottHermanFitness","checked":"2026-10-23"}]}'::jsonb),
('dead-bug', 'Dead Bug', 'abs', 'bodyweight', 'isolation', 'beginner', '{"slug":"dead-bug","name":"Dead Bug","aliases":["Dead Bug Exercise"],"muscle_group":"abs","secondary":["lower-back"],"equipment":"bodyweight","mechanic":"isolation","level":"beginner","summary":"A floor exercise that trains the abs to keep the lower back steady while the arms and legs move.","setup":["Lie on your back with the arms pointing to the ceiling and hips and knees bent at 90 degrees.","Press the lower back gently toward the floor and brace the abs.","Keep the ribs down."],"execution":["Slowly extend one arm overhead and the opposite leg toward the floor.","Stop before the lower back lifts off the floor.","Return to the start under control.","Repeat on the other side while breathing steadily."],"cues":["Lower back stays flat","Slow and controlled","Exhale as you extend"],"mistakes":["Arching the lower back: shorten the range of motion.","Moving too fast: slow the tempo.","Holding the breath: exhale as you extend.","Flaring the ribs: keep them drawn down."],"default_sets":3,"default_reps":"8-10 per side","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=GbSC02oU3To","title":"How to Do a Dead Bug: A Guide from Physical Therapists","author":"Hinge Health","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=0XVbn86Btj0","title":"You''re Doing Dead Bugs WRONG! Fix This for Stronger Abs & a Bulletproof Core","author":"Squat University","checked":"2026-10-23"}]}'::jsonb),
('decline-push-up', 'Decline Push-Up', 'chest', 'bodyweight', 'compound', 'intermediate', '{"slug":"decline-push-up","name":"Decline Push-Up","aliases":["Feet-Elevated Push-Up"],"muscle_group":"chest","secondary":["shoulders","triceps","abs"],"equipment":"bodyweight","mechanic":"compound","level":"intermediate","summary":"A push-up with the feet raised that puts more load on the upper chest and shoulders than a floor push-up.","setup":["Place your feet on a sturdy bench, sofa or chair and your hands on the floor slightly wider than your shoulders.","Make sure the support is stable and will not slide.","Brace your abs and squeeze your glutes so your body is straight.","Keep your head in line with your spine."],"execution":["Lower your chest toward the floor with elbows at about 45 degrees.","Keep your hips from sagging or piking.","Press the floor away to the start.","Use a lower platform if you cannot keep the line."],"cues":["Straight line, feet to head","Elbows at 45 degrees","Push the floor away"],"mistakes":["Hips sagging: brace the abs and squeeze glutes, or lower the foot height.","Shoulders shrugging up: keep them pulled down and away from the ears.","Elbows flaring: tuck them closer.","Feet on an unstable surface: use a sturdy one."],"default_sets":3,"default_reps":"8-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=QBlYp-EwHlo","title":"How To Do A Decline Push Up","author":"PureGym","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=5QFjmotLfW4","title":"How to perform decline push ups with good form","author":"Shawn Adair","checked":"2026-10-23"}]}'::jsonb),
('diamond-push-up', 'Diamond Push-Up', 'triceps', 'bodyweight', 'compound', 'intermediate', '{"slug":"diamond-push-up","name":"Diamond Push-Up","aliases":["Close-Grip Push-Up","Triangle Push-Up"],"muscle_group":"triceps","secondary":["chest","shoulders","abs"],"equipment":"bodyweight","mechanic":"compound","level":"intermediate","summary":"A narrow-hand push-up that shifts the emphasis to the triceps while still working the chest and shoulders.","setup":["Start in a push-up position with hands under your chest.","Bring your hands together so the thumbs and index fingers form a diamond or triangle.","Extend your legs, brace abs and squeeze glutes into a straight line.","If it is too hard, drop to your knees or place your hands on a bench."],"execution":["Lower your chest toward your hands, keeping your elbows close to your ribs.","Keep your body in one straight line.","Press through your palms to straighten your arms.","Look at the floor slightly ahead so your neck stays neutral."],"cues":["Elbows tucked","Body in a plank","Chest to hands"],"mistakes":["Elbows flaring: keep them close to your sides.","Hips sagging: squeeze glutes and brace the abs.","Wrist discomfort: set hands slightly wider apart than a full diamond, or use fists.","Cutting the range: lower until your chest is near your hands, or use an incline."],"default_sets":3,"default_reps":"6-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=J0DnG1_S92I","title":"How To: Diamond Push-Up","author":"ScottHermanFitness","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=kGhDnFwMY3E","title":"Diamond Push Ups For Beginners | Proper Form & Progression","author":"Minus The Gym","checked":"2026-10-23"}]}'::jsonb),
('donkey-kick', 'Donkey Kick', 'glutes', 'bodyweight', 'isolation', 'beginner', '{"slug":"donkey-kick","name":"Donkey Kick","aliases":["Quadruped Hip Extension","Glute Kickback"],"muscle_group":"glutes","secondary":["hamstrings"],"equipment":"bodyweight","mechanic":"isolation","level":"beginner","summary":"A quadruped hip extension that trains the glutes with no equipment.","setup":["Start on hands and knees, hands under shoulders and knees under hips.","Keep your spine neutral and brace your abs.","Look at the floor."],"execution":["Lift one leg, keeping the knee bent at 90 degrees.","Press the foot toward the ceiling until the thigh is in line with the torso.","Squeeze the glute at the top.","Lower slowly, then repeat before switching."],"cues":["Squeeze the glute","Ribs and hips square","No arching"],"mistakes":["Arching the lower back to kick higher: stop when the thigh aligns with the torso.","Twisting the hips: keep the pelvis level.","Swinging with momentum: slow down.","Dropping the chest: push the floor away."],"default_sets":3,"default_reps":"12-20 per side","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=YoOlLusFMYU","title":"How To Do Donkey Kicks","author":"Hinge Health","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=BNDw4ciQoQI","title":"Glute Kickbacks | Nuffield Health","author":"Nuffield Health","checked":"2026-10-23"}]}'::jsonb),
('dumbbell-alternating-curl', 'Dumbbell Alternating Curl', 'biceps', 'dumbbell', 'isolation', 'beginner', '{"slug":"dumbbell-alternating-curl","name":"Dumbbell Alternating Curl","aliases":["Alternating Bicep Curl","DB Alternating Curl"],"muscle_group":"biceps","secondary":["forearms"],"equipment":"dumbbell","mechanic":"isolation","level":"beginner","summary":"A classic arm exercise curling one dumbbell at a time. Alternating sides lets you focus on each arm and keep your torso still.","setup":["Stand tall with feet hip-width apart, a dumbbell in each hand with palms facing forward or in.","Keep your elbows beside your torso and your shoulders relaxed.","Brace your abs lightly to avoid leaning."],"execution":["Curl one dumbbell up toward your shoulder, rotating your palm to face up as it rises.","Keep your upper arm still and your elbow close to your side.","Squeeze at the top, then lower slowly until the arm is straight.","Repeat with the other arm."],"cues":["Elbows pinned to the sides","Palm turns up as you curl","Slow lowering","No swinging"],"mistakes":["Swinging the torso to lift the weight: use lighter dumbbells and keep your glutes tight.","Elbows drifting forward: keep them beside your ribs.","Dropping the weight on the way down: take two to three seconds to lower.","Cutting the range of motion: lower until the arm is nearly straight each rep."],"default_sets":3,"default_reps":"10-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=sAq_ocpRh_I","title":"How To: Alternating Dumbbell Curl","author":"ScottHermanFitness","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=jcA6wqA2Qso","title":"Alternating Dumbbell Curls  Correct Technique ✔️","author":"One Minute Tutorial","checked":"2026-10-23"}]}'::jsonb),
('dumbbell-bench-press', 'Dumbbell Bench Press', 'chest', 'dumbbell', 'compound', 'beginner', '{"slug":"dumbbell-bench-press","name":"Dumbbell Bench Press","aliases":["Flat Dumbbell Press","DB Bench Press"],"muscle_group":"chest","secondary":["triceps","shoulders"],"equipment":"dumbbell","mechanic":"compound","level":"beginner","summary":"A flat pressing movement with dumbbells that allows a deeper stretch and a more natural arm path than the barbell version, while training each side independently.","setup":["Sit on the end of a flat bench with the dumbbells resting on your thighs.","Lie back, kicking the dumbbells up to chest level one at a time or together.","Pull shoulder blades back and down, feet planted on the floor.","Press the dumbbells above the chest with palms facing forward or slightly angled in."],"execution":["Lower the dumbbells under control to the sides of the chest with elbows about 45-70 degrees from the torso.","Stop when the upper arms are around parallel to the floor or you feel a comfortable chest stretch.","Press up and slightly inward until the arms are straight, without clanking the dumbbells hard together.","Return the dumbbells to your thighs and sit up carefully when finished."],"cues":["Wrists over elbows","Squeeze the chest as you press","Slow lowering, steady press"],"mistakes":["Elbows flared out wide: angle them in toward 45-70 degrees.","Going too heavy and losing control: choose a weight you can lower for a 2-3 second count.","Lowering too deep so shoulders roll forward: stop at a comfortable stretch.","Hips lifting or back over-arching: keep glutes on the bench and feet planted."],"default_sets":3,"default_reps":"8-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=ueLm5WXddUA","title":"Dumbbell Bench Press for Maximum Growth and Injury Prevention (Proper Form Explained)","author":"Dave Rienzi","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=Soq7ElEu0MU","title":"Dumbbell Bench Press Exercise Tutorial || FIX YOUR FORM NOW + Muscle Gain Variations","author":"Colossus Fitness","checked":"2026-10-23"}]}'::jsonb),
('dumbbell-bent-over-row', 'Dumbbell Bent-Over Row', 'back', 'dumbbell', 'compound', 'beginner', '{"slug":"dumbbell-bent-over-row","name":"Dumbbell Bent-Over Row","aliases":["Two-Arm Dumbbell Row","DB Bent Over Row"],"muscle_group":"back","secondary":["lats","rear-delts","biceps"],"equipment":"dumbbell","mechanic":"compound","level":"beginner","summary":"A two-arm rowing movement from a hip-hinged position that builds the mid-back and lats and teaches a strong flat-back hinge.","setup":["Hold a dumbbell in each hand and stand with feet hip-width apart.","Hinge at the hips with soft knees until your torso is about 45 degrees to the floor, back flat.","Let the dumbbells hang below your shoulders with palms facing each other or facing you.","Look at a spot on the floor a little in front of you to keep the neck neutral."],"execution":["Pull your shoulder blades back and then drive your elbows toward your hips.","Bring the dumbbells to the sides of your lower ribs.","Squeeze your back for a moment at the top.","Lower with control until your arms are straight, without changing your torso angle."],"cues":["Elbows to the hips","Flat back, hips back","Squeeze the shoulder blades","Do not stand up with each rep"],"mistakes":["Rounding the back: lift the chest a little, push the hips back and use lighter weights.","Jerking the weight with body swing: hold your torso still and slow the lowering.","Pulling with the biceps only: think about driving the elbows back.","Rising up as you row: keep the same hinge angle throughout the set."],"default_sets":3,"default_reps":"8-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=6TSP1TRMUzs","title":"How To:  Dumbbell Bent-Over Row","author":"ScottHermanFitness","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=iCM5U0_b9Mg","title":"Dumbbell Bent Over Rows At Home (Exercise Tutorial + Form Tips) | Team Evolve","author":"Vivian Ngo","checked":"2026-10-23"}]}'::jsonb),
('dumbbell-floor-press', 'Dumbbell Floor Press', 'chest', 'dumbbell', 'compound', 'beginner', '{"slug":"dumbbell-floor-press","name":"Dumbbell Floor Press","aliases":["DB Floor Press"],"muscle_group":"chest","secondary":["triceps","shoulders"],"equipment":"dumbbell","mechanic":"compound","level":"beginner","summary":"A pressing movement lying on the floor, where the ground limits the range of motion. It trains the chest and triceps without a bench and is friendly to the shoulders.","setup":["Lie on your back with knees bent and feet flat on the floor.","Hold a dumbbell in each hand and bring your upper arms to the floor with elbows at roughly 45 degrees from your torso.","Hold the dumbbells over your chest or just outside it with palms facing your feet or each other.","Keep your wrists straight and your shoulder blades pulled back."],"execution":["Press the dumbbells up until your arms are straight above your chest.","Squeeze your chest at the top without shrugging.","Lower slowly until the backs of your upper arms lightly touch the floor.","Pause for a moment without relaxing, then press again."],"cues":["Elbows at 45 degrees","Wrists over elbows","Pause, do not bounce","Shoulder blades pinned"],"mistakes":["Flaring the elbows out wide: keep them about 45 degrees from your sides.","Dropping the arms onto the floor and bouncing: lower under control and pause briefly.","Letting the wrists bend back: stack the wrist over the forearm.","Arching the lower back to push more weight: keep feet flat and ribs down, and pick a lighter weight."],"default_sets":3,"default_reps":"8-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=Bx4QPVH-J1g","title":"Dumbbell Floor Press: The RIGHT Way (Most People Do This Wrong)","author":"Colossus Fitness","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=uUGDRwge4F8","title":"How To: Dumbbell Floor Press","author":"ScottHermanFitness","checked":"2026-10-23"}]}'::jsonb),
('dumbbell-fly', 'Dumbbell Fly', 'chest', 'dumbbell', 'isolation', 'intermediate', '{"slug":"dumbbell-fly","name":"Dumbbell Fly","aliases":["Dumbbell Chest Fly","Flat Dumbbell Fly"],"muscle_group":"chest","secondary":["shoulders"],"equipment":"dumbbell","mechanic":"isolation","level":"intermediate","summary":"An isolation movement that stretches and contracts the chest through a wide arc with the arms slightly bent.","setup":["Lie on a flat bench with a light dumbbell in each hand, feet planted.","Hold the dumbbells above the chest with palms facing each other.","Pull shoulder blades back and down.","Keep a soft, fixed bend in the elbows."],"execution":["Lower the dumbbells out to the sides in a wide arc, keeping the elbow bend constant.","Stop when you feel a stretch across the chest, around upper-arm parallel to the floor.","Bring the dumbbells back up in the same arc, as if hugging a barrel.","Finish with the weights over the chest without letting them clank."],"cues":["Hug a big tree","Fixed elbow bend","Stretch, don''t drop"],"mistakes":["Going too heavy: use a light load; this is an isolation exercise.","Lowering too deep so the shoulders roll forward: stop at a comfortable stretch.","Straightening and bending the elbows (turning it into a press): keep the angle fixed.","Letting the weights fall quickly: lower for 2-3 seconds."],"default_sets":3,"default_reps":"10-15","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=LBpdPSivCb4","title":"Correct Range of Motion for Dumbbell Chest Flys - Presented by Pivotal Motion Physiotherapy","author":"Pivotal Motion Physiotherapy - Physiotherapist Newmarket","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=QENKPHhQVi4","title":"How to Properly Do a DUMBBELL FLY | Mind Pump","author":"Mind Pump TV","checked":"2026-10-23"}]}'::jsonb),
('dumbbell-front-raise', 'Dumbbell Front Raise', 'shoulders', 'dumbbell', 'isolation', 'beginner', '{"slug":"dumbbell-front-raise","name":"Dumbbell Front Raise","aliases":["Front Raise"],"muscle_group":"shoulders","secondary":["chest"],"equipment":"dumbbell","mechanic":"isolation","level":"beginner","summary":"An isolation exercise for the front delts, raising dumbbells in front of the body to shoulder height.","setup":["Stand tall holding a light dumbbell in each hand in front of the thighs.","Keep a slight bend in the elbows.","Brace the core and keep the ribs down.","Grip palms down or neutral."],"execution":["Raise the dumbbells forward to about shoulder height.","Keep arms close to straight with the same elbow angle.","Pause, then lower under control.","Do not swing the torso."],"cues":["Ribs down","Raise to shoulder height","Slow and steady"],"mistakes":["Swinging the body: lower the weight and brace the core.","Raising too high with an arched back: stop at shoulder height.","Shrugging: keep shoulders down.","Rushing the lowering: control it."],"default_sets":3,"default_reps":"10-15","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=wp_TDRF2Bug","title":"Dumbbell Front Raise | Front Delt (Shoulder) Exercise | Proper Form Guide | Tutorial or Instruction","author":"Lean Physique Lab","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=k3WOtQtMkGI","title":"How to Do a Dumbbell Front Raise (Thumbs-Up Grip) | Safe Shoulder Strength & Upper Body Toning","author":"Conditioned by Kelly Tekin","checked":"2026-10-23"}]}'::jsonb),
('dumbbell-hammer-curl', 'Dumbbell Hammer Curl', 'biceps', 'dumbbell', 'isolation', 'beginner', '{"slug":"dumbbell-hammer-curl","name":"Dumbbell Hammer Curl","aliases":["Hammer Curl"],"muscle_group":"biceps","secondary":["forearms"],"equipment":"dumbbell","mechanic":"isolation","level":"beginner","summary":"A curl with a neutral (thumbs-up) grip that works the biceps and especially the brachialis and brachioradialis, which add thickness to the upper arm and forearm.","setup":["Stand tall holding a dumbbell in each hand with palms facing your thighs.","Keep elbows beside your ribs and shoulders relaxed.","Brace your abs and keep the wrists straight."],"execution":["Curl one or both dumbbells up, keeping the palms facing each other the whole way.","Stop when the forearms are close to vertical and squeeze briefly.","Lower the weights slowly to full arm extension.","Alternate arms or curl both together, keeping the torso still."],"cues":["Thumbs up the whole time","Elbows glued to your sides","Slow lowering"],"mistakes":["Swinging the weights with the hips: use lighter dumbbells and brace the core.","Letting the elbows drift forward: keep the upper arms vertical.","Rotating the palms up during the rep: that turns it into a regular curl, so keep the neutral grip.","Bending the wrists: hold the dumbbell in line with the forearm."],"default_sets":3,"default_reps":"8-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=Hy5L3-QJETc","title":"How to PROPERLY Dumbbell Hammer Curl (FIX THIS NOW!)","author":"Colossus Fitness","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=zC3nLlEvin4","title":"How To: Dumbbell Hammer Curl","author":"ScottHermanFitness","checked":"2026-10-23"}]}'::jsonb),
('dumbbell-hip-thrust', 'Dumbbell Hip Thrust', 'glutes', 'dumbbell', 'compound', 'beginner', '{"slug":"dumbbell-hip-thrust","name":"Dumbbell Hip Thrust","aliases":["DB Hip Thrust","Dumbbell Glute Bridge on Bench"],"muscle_group":"glutes","secondary":["hamstrings","quads"],"equipment":"dumbbell","mechanic":"compound","level":"beginner","summary":"A glute-focused hip extension done with your upper back on a bench or sofa and a dumbbell resting on your hips. It is one of the easiest ways to load the glutes at home.","setup":["Sit on the floor with your upper back (just below the shoulder blades) against a stable bench or the edge of a sofa. Make sure it cannot slide.","Roll a dumbbell onto your hip crease and hold it with both hands. Pad it with a towel if it is uncomfortable.","Place your feet hip-width apart, flat on the floor, with knees bent so the shins are roughly vertical at the top.","Tuck your chin slightly and keep your eyes forward."],"execution":["Drive through your heels and squeeze your glutes to lift your hips until your torso is roughly parallel to the floor.","At the top your ribs stay down and your shins are about vertical.","Pause for a moment, then lower your hips under control until they nearly touch the floor.","Repeat without bouncing off the floor."],"cues":["Heels down, hips up","Ribs down, chin tucked","Squeeze the glutes at the top","Shins vertical at the top"],"mistakes":["Arching the lower back at the top: tuck the ribs down and stop when hips and shoulders line up.","Feet too far forward or too close: adjust so the shins are vertical at the top and you feel it in the glutes, not the hamstrings or quads.","Bench or sofa sliding: push it against a wall or use a heavy piece of furniture.","Rushing with momentum: lower slowly and pause at the top of each rep."],"default_sets":3,"default_reps":"10-15","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=29OfN4ztW_g","title":"Dumbbell Hip Thrust (FULL TUTORIAL) - Glute Exercises for Beginners","author":"Mike | J2FIT Strength & Conditioning","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=T55MKVmc0G0","title":"Dumbbell Hip Thrust Form | How To Dumbbell Hip Thrust On a Bench","author":"Lift With Michelle - Exercise Form Tutorials","checked":"2026-10-23"}]}'::jsonb),
('dumbbell-lateral-raise', 'Dumbbell Lateral Raise', 'shoulders', 'dumbbell', 'isolation', 'beginner', '{"slug":"dumbbell-lateral-raise","name":"Dumbbell Lateral Raise","aliases":["Side Raise","Lateral Raise"],"muscle_group":"shoulders","secondary":[],"equipment":"dumbbell","mechanic":"isolation","level":"beginner","summary":"An isolation exercise for the side delts that builds shoulder width.","setup":["Stand tall with a light dumbbell in each hand at your sides.","Slightly bend your elbows and lean very slightly forward.","Pull shoulders back and down and brace the core.","Keep wrists neutral."],"execution":["Raise the arms out to the sides in a slight arc until about shoulder height.","Lead with the elbows rather than the hands.","Pause briefly, then lower under control.","Keep the torso still."],"cues":["Lead with the elbows","Raise to shoulder height","Slow lowering"],"mistakes":["Swinging the torso to lift: use a lighter weight and stay still.","Shrugging the traps: keep shoulders down.","Lifting above shoulder height: stop around parallel.","Dropping the weights quickly: control the descent."],"default_sets":3,"default_reps":"12-20","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=XPPfnSEATJA","title":"How to do a Dumbbell Lateral Raise","author":"National Academy of Sports Medicine (NASM)","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=1ovNfOjGN8Q","title":"Full ROM Dumbbell Lateral Raise (Proper Form)","author":"Mike | J2FIT Strength & Conditioning","checked":"2026-10-23"}]}'::jsonb),
('dumbbell-pullover', 'Dumbbell Pullover', 'lats', 'dumbbell', 'compound', 'beginner', '{"slug":"dumbbell-pullover","name":"Dumbbell Pullover","aliases":["DB Pullover","Straight-Arm Dumbbell Pullover"],"muscle_group":"lats","secondary":["chest","triceps"],"equipment":"dumbbell","mechanic":"compound","level":"beginner","summary":"An arcing movement where a single dumbbell travels from over the chest to behind the head. It stretches and trains the lats and chest, and works from the floor or a sofa edge.","setup":["Lie on your back on the floor or across a bench, with knees bent and feet flat.","Hold one end of a dumbbell with both hands, palms facing up under the top plate.","Press it over your chest with a slight bend in your elbows."],"execution":["Keeping your elbows slightly bent and fixed, lower the dumbbell in an arc back behind your head.","Stop when you feel a stretch in your lats and chest, or when your arms are about level with your ears.","Pull the dumbbell back over your chest using your lats, moving along the same arc.","Keep your ribs down so the lower back does not arch."],"cues":["Wide arc, fixed elbows","Ribs down","Pull with the lats","Stop at a comfortable stretch"],"mistakes":["Arching the lower back at the bottom: reduce the range and keep ribs down.","Bending and straightening the elbows like a triceps extension: keep the elbow angle constant.","Using too heavy a weight: choose a load you can control with both hands and no strain on the shoulders.","Letting the dumbbell slip: grip the inside of the top plate firmly with both palms."],"default_sets":3,"default_reps":"10-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=tpLnfSQJ0gg","title":"How To: Dumbbell Pull-Over","author":"ScottHermanFitness","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=5YStMv6m2g8","title":"Dumbbell Pullover: Chest or Back Exercise?","author":"Muscle & Strength","checked":"2026-10-23"}]}'::jsonb),
('dumbbell-renegade-row', 'Dumbbell Renegade Row', 'back', 'dumbbell', 'compound', 'intermediate', '{"slug":"dumbbell-renegade-row","name":"Dumbbell Renegade Row","aliases":["Renegade Row","Plank Row"],"muscle_group":"back","secondary":["abs","lats","shoulders","biceps"],"equipment":"dumbbell","mechanic":"compound","level":"intermediate","summary":"A row performed from a push-up plank position on two dumbbells. It trains the back while the trunk fights to resist rotation, making it a strong core and back combination.","setup":["Place two hex or fixed dumbbells on the floor, shoulder-width apart, so they cannot roll.","Get into a push-up position with your hands gripping the dumbbells and feet wider than hip-width for balance.","Brace your abs and squeeze your glutes so your body forms a straight line from head to heels."],"execution":["Shift your weight slightly onto the left hand and row the right dumbbell toward your lower ribs.","Keep your hips level and square to the floor while you row.","Lower the dumbbell back to the floor with control.","Repeat on the other side, alternating, and rest the dumbbell fully before changing sides."],"cues":["Hips stay level","Pull the elbow to the hip","Squeeze the glutes","Wide feet for stability"],"mistakes":["Twisting the hips as you row: widen your feet and brace harder, or kneel to regress.","Sagging in the lower back: squeeze the glutes and keep ribs down.","Using round dumbbells that roll: use hex or fixed dumbbells, or switch to hands on a stable platform.","Using too much weight: pick light dumbbells so every rep keeps the plank solid."],"default_sets":3,"default_reps":"6-10","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=4qEIChzM4ZA","title":"Renegade Row Guide | Form Tips, Muscles Worked, and Variations","author":"BarBend","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=ZMW_vIWH5D8","title":"How to Master Dumbbell Renegade Rows for a Stronger Core & Back","author":"Coach Nick Fitness","checked":"2026-10-23"}]}'::jsonb),
('dumbbell-reverse-lunge', 'Dumbbell Reverse Lunge', 'quads', 'dumbbell', 'compound', 'beginner', '{"slug":"dumbbell-reverse-lunge","name":"Dumbbell Reverse Lunge","aliases":["Reverse Lunge","Backward Lunge"],"muscle_group":"quads","secondary":["glutes","hamstrings"],"equipment":"dumbbell","mechanic":"compound","level":"beginner","summary":"A lunge where you step backward, which is often easier on the knees and balance than a forward lunge and loads the glutes and quads.","setup":["Hold a dumbbell in each hand at your sides.","Stand tall with your feet about hip width apart.","Brace your trunk and set your shoulders back."],"execution":["Step one foot straight back and land on the ball of your foot.","Lower your hips until your front thigh is about parallel and your back knee nearly touches the floor.","Keep most of your weight on the front foot with the torso upright.","Push through the front foot to return to standing, bringing your back foot back to the start.","Repeat on the same leg or alternate legs."],"cues":["Step back, drop down","Weight on the front heel","Torso tall"],"mistakes":["Front knee collapsing inward: push it out in line with the toes.","Taking too short a step so the front knee shoots far forward: step back farther.","Pushing off the back foot: drive through the front foot to stand.","Leaning forward: keep your chest up and brace your trunk."],"default_sets":3,"default_reps":"8-12 per leg","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=Q2k3kYbtOcI","title":"Dumbbell Reverse Lunge","author":"OPEX Fitness","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=jklUSipBe28","title":"DB Reverse Lunge (Exercise Library)","author":"Horton Barbell","checked":"2026-10-23"}]}'::jsonb),
('dumbbell-romanian-deadlift', 'Dumbbell Romanian Deadlift', 'hamstrings', 'dumbbell', 'compound', 'beginner', '{"slug":"dumbbell-romanian-deadlift","name":"Dumbbell Romanian Deadlift","aliases":["Dumbbell RDL","DB RDL"],"muscle_group":"hamstrings","secondary":["glutes","lower-back"],"equipment":"dumbbell","mechanic":"compound","level":"beginner","summary":"A hip-hinge that loads the hamstrings and glutes with a pair of dumbbells. It is easy to do at home and teaches the hinge pattern that carries over to deadlifts and jumping.","setup":["Hold a dumbbell in each hand in front of your thighs, palms facing you. Two filled backpacks or water-bottle jugs work as a home substitute.","Stand with feet hip-width apart and a soft bend in the knees.","Pull your shoulders back and down and brace your trunk."],"execution":["Push your hips straight back as if closing a door behind you with your glutes, keeping the knees only slightly bent.","Slide the dumbbells down close to your thighs and shins while your back stays flat.","Stop when you feel a strong stretch in the hamstrings, usually around mid-shin, before your back starts to round.","Squeeze your glutes and drive your hips forward to stand tall, keeping the weights close to your legs."],"cues":["Hips back, not down","Dumbbells brush the legs","Long, flat spine","Stand up by squeezing the glutes"],"mistakes":["Rounding the lower back: shorten the range and only lower as far as you can keep a neutral spine.","Turning it into a squat by bending the knees a lot: keep the knees nearly fixed and move the hips back.","Letting the weights drift forward: keep them in contact with your thighs and shins.","Leaning back at the top: finish with hips under shoulders and ribs down instead of hyperextending."],"default_sets":3,"default_reps":"8-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=aa57T45iFSE","title":"How to do a Dumbbell Romanian Deadlift | Proper Form & Technique | NASM","author":"National Academy of Sports Medicine (NASM)","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=uUjqvxEWcbo","title":"Dumbbell Romanian Deadlift (RDL) | TECHNIQUE for Beginners","author":"Mobility Doc","checked":"2026-10-23"}]}'::jsonb),
('dumbbell-shrug', 'Dumbbell Shrug', 'traps', 'dumbbell', 'isolation', 'beginner', '{"slug":"dumbbell-shrug","name":"Dumbbell Shrug","aliases":["DB Shrug"],"muscle_group":"traps","secondary":["forearms","shoulders"],"equipment":"dumbbell","mechanic":"isolation","level":"beginner","summary":"A shrug with dumbbells at the sides that loads the upper traps and lets the hands hang in a natural position.","setup":["Stand tall holding a dumbbell in each hand at your sides, palms facing in.","Keep the chest up, the abs braced and the head neutral.","Let the shoulders hang relaxed with straight arms."],"execution":["Lift the shoulders straight up toward the ears.","Squeeze and pause at the top.","Lower slowly to a full relaxed hang.","Keep the arms straight and the torso still."],"cues":["Shoulders straight to ears","Squeeze at the top","Slow lowering"],"mistakes":["Rolling the shoulders in circles: move straight up and down.","Using momentum from the legs: stand still and slow down.","Neck jutting forward: keep the head stacked over the shoulders.","Grip failing first: use straps on the heaviest sets."],"default_sets":3,"default_reps":"10-15","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=lPz7WAXKk8I","title":"How To Isolate The Upper Trap and Rhomboids with The Dumbbell Shrug","author":"Mind Pump TV","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=qvvJUKq7_sU","title":"How To Perform Dumbbell Shrugs | Build Trap Size Exercise Tutorial","author":"Buff Dudes Workouts","checked":"2026-10-23"}]}'::jsonb),
('dumbbell-single-leg-romanian-deadlift', 'Dumbbell Single-Leg Romanian Deadlift', 'hamstrings', 'dumbbell', 'compound', 'intermediate', '{"slug":"dumbbell-single-leg-romanian-deadlift","name":"Dumbbell Single-Leg Romanian Deadlift","aliases":["Single-Leg DB RDL","One-Leg Dumbbell Deadlift"],"muscle_group":"hamstrings","secondary":["glutes","lower-back","abs"],"equipment":"dumbbell","mechanic":"compound","level":"intermediate","summary":"A single-leg hip hinge that loads the hamstrings and glutes and challenges balance and trunk control. Light weights are enough to make it hard.","setup":["Hold a dumbbell in one or both hands in front of your thighs.","Stand on one leg with a soft bend in the standing knee. Keep a hand near a wall or chair for balance when learning.","Keep your hips and shoulders square to the floor."],"execution":["Hinge at the hip and send your free leg straight back behind you as your torso lowers.","Keep your back flat and the dumbbell close to your standing leg.","Lower until your torso is near parallel to the floor or you feel a stretch in the hamstring of the standing leg.","Squeeze the glute and drive your hips forward to stand tall again."],"cues":["Hips square to the floor","Long line from head to heel","Hips back, not knee forward","Dumbbell close to the leg"],"mistakes":["Rotating the hips open: keep both hip bones facing the floor.","Rounding the back: shorten the range and keep the spine long.","Losing balance: fix your eyes on a point on the floor and use a wall for support.","Locking the standing knee: keep it softly bent."],"default_sets":3,"default_reps":"8-10","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=GY3xKrda3U4","title":"Dumbbell Single Leg Deadlift Variations Tutorial | RDL","author":"Lift With Michelle - Exercise Form Tutorials","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=_DhDkij1vxY","title":"Single-Leg Dumbbell RDL | Olympic Weightlifting Exercise Library","author":"Catalyst Athletics","checked":"2026-10-23"}]}'::jsonb),
('dumbbell-skull-crusher', 'Dumbbell Skull Crusher', 'triceps', 'dumbbell', 'isolation', 'beginner', '{"slug":"dumbbell-skull-crusher","name":"Dumbbell Skull Crusher","aliases":["Dumbbell Lying Triceps Extension","DB Skullcrusher"],"muscle_group":"triceps","secondary":[],"equipment":"dumbbell","mechanic":"isolation","level":"beginner","summary":"A lying triceps extension where the dumbbells lower toward the sides of the head. It isolates the triceps and is easy to do on a bench, sofa edge or the floor.","setup":["Lie on your back on the floor or a bench with feet flat. Hold a dumbbell in each hand with a neutral (palms facing in) grip.","Press the dumbbells straight up over your shoulders.","Keep your upper arms vertical and your shoulder blades pulled back."],"execution":["Bend only at the elbows to lower the dumbbells toward the sides of your head, keeping your upper arms still.","Lower until you feel a stretch in the triceps, keeping control.","Extend your elbows to return to the top, squeezing the triceps.","Keep your wrists straight throughout."],"cues":["Only the elbows move","Upper arms vertical","Slow and controlled","Squeeze at the top"],"mistakes":["Letting the elbows flare out: keep them pointing at the ceiling and shoulder-width apart.","Letting the upper arms drift back, turning it into a pullover: keep them vertical.","Using too much weight: start light and keep control, because the weights pass close to the head.","Bending the wrists: keep them neutral and aligned with the forearms."],"default_sets":3,"default_reps":"10-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=ir5PsbniVSc","title":"How To: Dumbbell Skull Crusher","author":"ScottHermanFitness","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=N5ImCU0mcpo","title":"Dumbbell Tricep Skullcrusher","author":"Movement As Medicine","checked":"2026-10-23"}]}'::jsonb),
('dumbbell-split-squat', 'Dumbbell Split Squat', 'quads', 'dumbbell', 'compound', 'beginner', '{"slug":"dumbbell-split-squat","name":"Dumbbell Split Squat","aliases":["DB Split Squat","Stationary Lunge with Dumbbells"],"muscle_group":"quads","secondary":["glutes","hamstrings"],"equipment":"dumbbell","mechanic":"compound","level":"beginner","summary":"A stationary single-leg squat in a split stance that builds quads and glutes and improves balance. It needs very little space at home.","setup":["Hold a dumbbell in each hand at your sides.","Take a long step forward and keep both feet pointing straight ahead, with the back heel lifted.","Stand tall with your torso upright and weight spread across the front foot."],"execution":["Bend both knees and lower your back knee straight down toward the floor.","Keep your front shin fairly vertical, with the front knee tracking over the toes.","Lower until the back knee almost touches the floor or until you reach your comfortable depth.","Press through the front foot to rise, without moving your feet."],"cues":["Straight down, straight up","Tall torso","Front foot flat","Back knee drops to the floor"],"mistakes":["Stance too short: take a longer step so the front heel stays down.","Torso leaning forward: keep chest tall and weights at your sides.","Front knee collapsing inward: push it out over the middle toes.","Balance wobbling: hold a chair or wall with one hand until you are steady."],"default_sets":3,"default_reps":"8-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=la0pLPq-3A8","title":"How to do the perfect SPLIT SQUAT: technique and common mistakes","author":"Get Exercise Confident","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=uyzVYAMhrEo","title":"How to do Dumbbell Split Squats","author":"Famme","checked":"2026-10-23"}]}'::jsonb),
('dumbbell-squeeze-press', 'Dumbbell Squeeze Press', 'chest', 'dumbbell', 'isolation', 'beginner', '{"slug":"dumbbell-squeeze-press","name":"Dumbbell Squeeze Press","aliases":["Svend Press Dumbbell","DB Squeeze Press"],"muscle_group":"chest","secondary":["triceps","shoulders"],"equipment":"dumbbell","mechanic":"isolation","level":"beginner","summary":"A press where you squeeze two dumbbells together the whole time, creating constant tension in the inner chest. It works well on the floor or a bench with light weights.","setup":["Lie on your back on the floor or a bench with knees bent and feet flat.","Hold two dumbbells together over your chest, with the inner ends pressed against each other and palms facing in.","Pull your shoulder blades back and keep your elbows at about 45 degrees."],"execution":["Squeeze the dumbbells together as hard as you can and keep that pressure throughout the set.","Press them up until your arms are straight over your chest.","Lower slowly back to your chest while still squeezing.","Stop just before the weights lose contact and repeat."],"cues":["Crush the dumbbells together","Elbows tucked","Slow and tight","Light weight, hard squeeze"],"mistakes":["Letting the dumbbells drift apart: use a lighter weight and focus on the squeeze.","Flaring the elbows: keep them tucked close to your torso.","Arching the lower back: keep your feet flat and ribs down.","Rushing the reps: use a slow tempo, since the tension comes from the squeeze rather than the load."],"default_sets":3,"default_reps":"10-15","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=rHfxaP0iF1E","title":"Dumbbell Chest Squeeze Press: Technique, Sets, Reps & Mistakes","author":"Mike | J2FIT Strength & Conditioning","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=Esg0M2uc_3o","title":"Dumbbell Squeeze Press Chest Press | Exercise Tutorial","author":"Lift With Michelle - Exercise Form Tutorials","checked":"2026-10-23"}]}'::jsonb),
('dumbbell-standing-overhead-press', 'Dumbbell Standing Overhead Press', 'shoulders', 'dumbbell', 'compound', 'beginner', '{"slug":"dumbbell-standing-overhead-press","name":"Dumbbell Standing Overhead Press","aliases":["Standing Dumbbell Shoulder Press","DB Overhead Press"],"muscle_group":"shoulders","secondary":["triceps","abs","traps"],"equipment":"dumbbell","mechanic":"compound","level":"beginner","summary":"A standing press that builds the shoulders and triceps while the trunk and glutes work to keep you stable. It needs only a pair of dumbbells or filled bags.","setup":["Stand with feet about hip- to shoulder-width apart, knees soft.","Bring the dumbbells to shoulder height with palms facing forward or slightly inward and forearms vertical.","Squeeze your glutes and brace your trunk so your ribs stay down."],"execution":["Press the dumbbells straight up until your arms are almost fully extended above your shoulders.","Move your head slightly forward at the top so the weights finish over the middle of your body.","Lower under control back to shoulder height.","Keep your torso upright for the entire set."],"cues":["Ribs down, glutes tight","Press up and slightly back","Forearms vertical","Control the way down"],"mistakes":["Leaning back and arching the lower back: squeeze the glutes, brace the abs and use a lighter weight.","Pressing forward in front of the body: keep the forearms vertical and finish over the shoulders.","Using leg drive by accident: keep the knees still unless you intend a push press.","Shrugging up to the ears at the top: keep the neck long and shoulders pressed down."],"default_sets":3,"default_reps":"8-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=bmy7tIopNt4","title":"Standing Dumbbell Shoulder Press (Tutorial + Tips) | Team Evolve","author":"Vivian Ngo","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=B-aVuyhvLHU","title":"How to Do a Dumbbell Shoulder Press","author":"LIVESTRONG","checked":"2026-10-23"}]}'::jsonb),
('dumbbell-step-up', 'Dumbbell Step-Up', 'quads', 'dumbbell', 'compound', 'beginner', '{"slug":"dumbbell-step-up","name":"Dumbbell Step-Up","aliases":["Step-Up","Weighted Step-Up"],"muscle_group":"quads","secondary":["glutes","hamstrings","calves"],"equipment":"dumbbell","mechanic":"compound","level":"beginner","summary":"A single-leg exercise stepping up onto a box with dumbbells to train the quads and glutes and build unilateral strength.","setup":["Place a sturdy box or bench in front of you, about knee height or lower.","Hold a dumbbell in each hand at your sides.","Stand tall with your feet hip width apart and brace your trunk."],"execution":["Place your whole front foot on the box.","Press through the front foot to stand up, bringing the other foot onto the box.","Stand tall at the top, then lower the trailing leg back down slowly under control.","Keep the movement driven by the working leg rather than pushing off the back foot.","Complete all reps on one leg, then switch, or alternate legs."],"cues":["Drive through the front heel","Stand tall at the top","Control the lowering"],"mistakes":["Pushing off the floor foot: keep it light and let the top leg do the work.","Box too high, causing the torso to lean forward: use a lower box.","Letting the knee cave in: push it out in line with the toes.","Dropping down quickly: lower slowly with control."],"default_sets":3,"default_reps":"8-12 per leg","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=x0cFKaepMXo","title":"How to PROPERLY Dumbbell Step Up (DO THIS NOW!)","author":"Colossus Fitness","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=Zp7RG4jFScw","title":"Dumbbell Step Up - OPEX Exercise Library","author":"OPEX Fitness","checked":"2026-10-23"}]}'::jsonb),
('dumbbell-sumo-squat', 'Dumbbell Sumo Squat', 'quads', 'dumbbell', 'compound', 'beginner', '{"slug":"dumbbell-sumo-squat","name":"Dumbbell Sumo Squat","aliases":["DB Sumo Squat","Wide-Stance Dumbbell Squat"],"muscle_group":"quads","secondary":["glutes","hamstrings"],"equipment":"dumbbell","mechanic":"compound","level":"beginner","summary":"A wide-stance squat holding one dumbbell between the legs. It keeps the torso upright, trains the quads and glutes, and is gentle to learn at home.","setup":["Stand with feet clearly wider than shoulder width and toes turned out about 30-45 degrees.","Hold one end of a dumbbell with both hands in front of your hips, arms straight. A heavy backpack held by its top handle also works.","Lift your chest and brace your trunk."],"execution":["Bend your knees and push them out over your toes as you lower straight down between your feet.","Keep your torso tall while the dumbbell hangs between your legs.","Lower until your thighs are about parallel to the floor, or as deep as you can control.","Push through your whole foot and squeeze your glutes to stand up."],"cues":["Knees follow the toes","Straight down, not forward","Tall chest","Spread the floor apart"],"mistakes":["Knees caving inward: push them out in line with the toes and widen the stance a little.","Leaning forward: keep the chest up and the weight close to the body.","Heels lifting: shift weight to the midfoot and heel, and reduce depth if needed.","Toes turned out too far for your hips: use an angle that lets your knees track comfortably over your feet."],"default_sets":3,"default_reps":"10-15","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=2zL-1TYsN_A","title":"Dumbbell Sumo Squat: Cues & Common Mistakes","author":"Katie Orlic","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=MwNY25e4QEA","title":"How To: Dumbbell Sumo Squat","author":"Live Lean TV Daily Exercises","checked":"2026-10-23"}]}'::jsonb),
('dumbbell-thruster', 'Dumbbell Thruster', 'quads', 'dumbbell', 'compound', 'intermediate', '{"slug":"dumbbell-thruster","name":"Dumbbell Thruster","aliases":["DB Thruster","Squat to Press"],"muscle_group":"quads","secondary":["glutes","shoulders","triceps","abs"],"equipment":"dumbbell","mechanic":"compound","level":"intermediate","summary":"A full-body movement that links a front squat with an overhead press in one smooth motion. It builds leg and shoulder strength and raises the heart rate fast.","setup":["Hold a dumbbell in each hand at shoulder height with palms facing each other, elbows slightly in front of the body.","Stand with feet shoulder-width apart and toes slightly turned out.","Brace your trunk and keep your chest up."],"execution":["Sit into a squat, pushing your knees out over your toes, until your thighs are about parallel to the floor.","Keep the dumbbells at your shoulders and your torso tall.","Drive up through your whole foot and use that momentum to press the dumbbells overhead.","Finish with arms straight over your shoulders and legs extended, then lower the weights back to shoulder height and go into the next squat."],"cues":["Squat deep, stand fast","Use the legs to start the press","Finish tall, arms locked overhead","Weights stay close to the shoulders"],"mistakes":["Pressing before the legs finish: let the legs extend and then send the weights up.","Leaning forward in the squat: keep the chest up and elbows forward.","Lower back arching at lockout: squeeze the glutes and brace the abs.","Going too heavy: pick a weight you can control for all reps, since fatigue builds quickly."],"default_sets":3,"default_reps":"8-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=tJP-fwf5ASA","title":"Dumbbell Thruster (FULL TUTORIAL) - Intense Full-Body Dumbbell Exercises","author":"Mike | J2FIT Strength & Conditioning","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=u3wKkZjE8QM","title":"The Dumbbell Thruster","author":"CrossFit","checked":"2026-10-23"}]}'::jsonb),
('dumbbell-triceps-kickback', 'Dumbbell Triceps Kickback', 'triceps', 'dumbbell', 'isolation', 'beginner', '{"slug":"dumbbell-triceps-kickback","name":"Dumbbell Triceps Kickback","aliases":["Triceps Kickback","DB Kickback"],"muscle_group":"triceps","secondary":[],"equipment":"dumbbell","mechanic":"isolation","level":"beginner","summary":"A bent-over triceps isolation exercise where you straighten the elbow behind you. It needs only light dumbbells and trains the triceps at full contraction.","setup":["Hold a dumbbell in each hand, or one dumbbell while supporting yourself with the other hand on a chair or sofa.","Hinge forward at the hips with a flat back until the torso is about 45 degrees, knees soft.","Bring your upper arms alongside your torso, parallel to the floor, with elbows bent to 90 degrees."],"execution":["Keeping your upper arm still, extend your elbow until your arm is straight behind you.","Squeeze your triceps for a moment at the end.","Lower slowly back to 90 degrees.","Keep your torso still the whole time."],"cues":["Upper arm glued to the torso","Straighten fully, squeeze","Slow back down","Still torso"],"mistakes":["Swinging the weight: use a lighter dumbbell and move only at the elbow.","Dropping the elbow: keep the upper arm in line with your back.","Rounding the back: keep a flat back and hinge at the hips, or support yourself on a chair.","Stopping short of full extension: finish each rep with a straight arm."],"default_sets":3,"default_reps":"10-15","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=XuH2W_R5YoA","title":"How To PROPERLY Tricep Dumbbell Kickback (FIX THIS NOW)","author":"Colossus Fitness","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=6SS6K3lAwZ8","title":"How To: Tricep Kickback (Dumbbell)","author":"ScottHermanFitness","checked":"2026-10-23"}]}'::jsonb),
('dumbbell-walking-lunge', 'Dumbbell Walking Lunge', 'quads', 'dumbbell', 'compound', 'intermediate', '{"slug":"dumbbell-walking-lunge","name":"Dumbbell Walking Lunge","aliases":["Walking Lunge"],"muscle_group":"quads","secondary":["glutes","hamstrings","abs"],"equipment":"dumbbell","mechanic":"compound","level":"intermediate","summary":"A walking, single-leg movement with dumbbells that trains the quads and glutes while challenging balance and coordination.","setup":["Pick up a dumbbell in each hand and hold them at your sides.","Stand tall with your feet about hip width apart and brace your trunk.","Clear a lane about 10 to 15 steps long."],"execution":["Take a long step forward and plant your whole foot.","Lower straight down until your back knee approaches the floor and the front thigh is about parallel.","Keep your torso upright and your front knee in line with your toes.","Push through the front foot to stand up and bring the back leg forward into the next step.","Alternate legs and walk the lane, turning around to return if needed."],"cues":["Long step, tall torso","Drop straight down","Front knee over toes","Push through the front heel"],"mistakes":["Taking steps that are too short so the front knee runs far past the toes: take a longer stride.","Leaning forward: keep your chest up and the dumbbells at your sides.","Knee collapsing inward: push the front knee out in line with the toes.","Rushing and losing balance: slow the pace and lighten the dumbbells."],"default_sets":3,"default_reps":"10-12 per leg","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=I34ysEkPK7w","title":"Dumbbell Walking Lunge - How To","author":"Bobby Maximus","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=4iDkpG1eBCk","title":"Master Your Dumbbell Walking Lunges: Avoid Common Mistakes For Stronger Legs | J2FIT","author":"Mike | J2FIT Strength & Conditioning","checked":"2026-10-23"}]}'::jsonb),
('ez-bar-curl', 'EZ-Bar Curl', 'biceps', 'ez-bar', 'isolation', 'beginner', '{"slug":"ez-bar-curl","name":"EZ-Bar Curl","aliases":["EZ Bar Bicep Curl","Cambered Bar Curl"],"muscle_group":"biceps","secondary":["forearms"],"equipment":"ez-bar","mechanic":"isolation","level":"beginner","summary":"A biceps curl with a zig-zag bar whose angled grips let the forearms turn slightly inward. Many lifters find it more comfortable on the wrists and elbows than a straight bar.","setup":["Load the EZ bar and hold it on the inner or outer angled grips with palms facing up and forward.","Stand tall with feet hip-width apart, bar hanging at thigh level and elbows at your sides.","Brace your abs and keep the chest up."],"execution":["Curl the bar toward your shoulders by bending the elbows only.","Squeeze the biceps at the top without letting the elbows travel forward.","Lower the bar under control until the arms are nearly straight.","Repeat without swinging the torso."],"cues":["Elbows stay beside the ribs","Curl the bar toward the collarbone","Control the lowering phase"],"mistakes":["Leaning back to finish the rep: reduce the weight and keep the ribs down.","Gripping too wide on the bar so the wrists flare: use the grip position that keeps your wrists comfortable and straight.","Letting the shoulders shrug up: keep the shoulders relaxed and away from the ears.","Dropping the bar after the top: lower it slowly for about 2-3 seconds."],"default_sets":3,"default_reps":"8-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=6LrOTcr595A","title":"EZ Bar Curls How To Perform Them Correctly","author":"KAGED ","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=aEscWJ3dS3w","title":"How To: Outside-Grip EZ-Bar Curl","author":"ScottHermanFitness","checked":"2026-10-23"}]}'::jsonb),
('face-pull', 'Face Pull', 'rear-delts', 'cable', 'isolation', 'beginner', '{"slug":"face-pull","name":"Face Pull","aliases":["Cable Face Pull","Rope Face Pull"],"muscle_group":"rear-delts","secondary":["traps","back"],"equipment":"cable","mechanic":"isolation","level":"beginner","summary":"A cable pull toward the face that targets the rear delts and upper back, often used for shoulder balance.","setup":["Attach a rope to a cable at about upper chest to face height.","Grip the ends with palms facing in, step back until the cable is taut.","Stand tall with a staggered stance and braced core.","Start with arms extended in front of you."],"execution":["Pull the rope toward your face, leading with the hands and elbows high.","Pull the rope ends apart as they approach your ears.","Squeeze the rear delts and upper back for a second.","Return slowly to the start."],"cues":["Elbows high","Pull apart at the end","Slow release"],"mistakes":["Leaning back with momentum: lower the weight and stay tall.","Elbows dropping low: keep them at or above hand level.","Using only the arms: think about pulling the shoulder blades back.","Going too heavy: use a weight that lets you pause."],"default_sets":3,"default_reps":"12-20","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=DvjmJdEswQ4","title":"Face Pulls | Proper Form vs Common Mistakes","author":"JONNI SHREVE","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=3pToT5_DUiY","title":"How To Properly Perform Face Pulls For Rear Delts / Fix Your Form","author":"Colossus Fitness","checked":"2026-10-23"}]}'::jsonb),
('farmers-carry', 'Farmer''s Carry', 'forearms', 'dumbbell', 'compound', 'beginner', '{"slug":"farmers-carry","name":"Farmer''s Carry","aliases":["Farmer''s Walk","Farmers Walk"],"muscle_group":"forearms","secondary":["traps","abs"],"equipment":"dumbbell","mechanic":"compound","level":"beginner","summary":"A loaded walk that builds grip strength, trap and core stability and general carrying capacity.","setup":["Place two heavy dumbbells or handles at your sides and hinge down with a flat back.","Grip them firmly and stand up tall.","Pull the shoulder blades down and back and brace the abs."],"execution":["Walk with short, quick steps, keeping the torso upright.","Keep the weights hanging by your sides without swinging.","Breathe steadily and keep the head neutral.","Walk for the set distance or time, then lower the weights under control."],"cues":["Tall posture","Strong grip","Short, steady steps"],"mistakes":["Leaning to one side: use equal loads and keep the shoulders level.","Shrugging the shoulders up: keep them down and packed.","Taking long, bouncing steps: shorten the stride.","Letting the grip fail early: use a weight you can hold for the whole distance."],"default_sets":3,"default_reps":"30-40 m","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=E94UNm8fD-4","title":"How To Do The Farmers Walk Exercise PROPERLY (Step-By-Step Tutorial)","author":"Colossus Fitness","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=lLAw6fUccKA","title":"Farmer''s Carry Tutorial - Proper Form and Technique","author":"Runna","checked":"2026-10-23"}]}'::jsonb),
('fire-hydrant', 'Fire Hydrant', 'glutes', 'bodyweight', 'isolation', 'beginner', '{"slug":"fire-hydrant","name":"Fire Hydrant","aliases":["Hip Abduction on All Fours","Quadruped Hip Abduction"],"muscle_group":"glutes","secondary":[],"equipment":"bodyweight","mechanic":"isolation","level":"beginner","summary":"A quadruped hip abduction that trains the outer glutes and hip stability.","setup":["Start on hands and knees, hands under shoulders and knees under hips.","Keep your back flat and abs braced.","Look at the floor."],"execution":["Lift one knee out to the side, keeping it bent at 90 degrees.","Raise it to about hip height without rotating the torso.","Pause and squeeze the outer hip.","Lower under control and repeat."],"cues":["Hips stay square","Lift from the glute","Slow down"],"mistakes":["Torso tilting or shifting: brace the abs and reduce the height.","Rocking the pelvis: lift only as high as the hips stay level.","Using momentum: slow down.","Collapsing into the shoulders: press the floor away."],"default_sets":3,"default_reps":"12-15 per side","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=IRkRgk2Gc1E","title":"How to Do a Fire Hydrant Exercise: A Guide from Physical Therapists","author":"Hinge Health","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=KOMtxRvGACA","title":"Master the Fire Hydrant Exercise: Proper Technique & Common Mistakes to Avoid!","author":"Mobility Doc","checked":"2026-10-23"}]}'::jsonb),
('glute-bridge', 'Glute Bridge', 'glutes', 'bodyweight', 'compound', 'beginner', '{"slug":"glute-bridge","name":"Glute Bridge","aliases":["Floor Glute Bridge","Hip Bridge"],"muscle_group":"glutes","secondary":["hamstrings","abs"],"equipment":"bodyweight","mechanic":"compound","level":"beginner","summary":"A floor-based hip extension that trains the glutes with minimal equipment. It is a good starting point for the hip thrust and for glute activation.","setup":["Lie on your back with your knees bent and your feet flat on the floor about hip width apart.","Place your heels about a foot from your hips and rest your arms by your sides.","Gently brace your abs and tuck your pelvis slightly."],"execution":["Press through your heels and lift your hips toward the ceiling.","Squeeze your glutes at the top until your knees, hips and shoulders form a straight line.","Keep your ribs down and avoid arching your lower back.","Pause briefly, then lower your hips under control.","Repeat for the set."],"cues":["Press through the heels","Ribs down","Squeeze the glutes at the top"],"mistakes":["Arching the lower back at the top: tuck the pelvis and lift only until the body is in a straight line.","Pushing through the toes so the hamstrings take over: place the feet closer and drive with the heels.","Letting the knees fall in or out: keep them in line with the toes.","Rushing the reps: pause at the top and lower slowly."],"default_sets":3,"default_reps":"12-20","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=u30lAKHl43Y","title":"Glute Bridges | How To | Proper Form & Technique","author":"FITTR","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=Q_Bpj91Yiis","title":"Glute Bridge Exercise - The correct way of doing it","author":"PostureFlow","checked":"2026-10-23"}]}'::jsonb),
('goblet-squat', 'Goblet Squat', 'quads', 'dumbbell', 'compound', 'beginner', '{"slug":"goblet-squat","name":"Goblet Squat","aliases":["Dumbbell Goblet Squat","Kettlebell Goblet Squat"],"muscle_group":"quads","secondary":["glutes","abs","hamstrings"],"equipment":"dumbbell","mechanic":"compound","level":"beginner","summary":"A beginner-friendly squat where a dumbbell or kettlebell held at the chest acts as a counterweight, making it easy to sit upright and learn good squat mechanics.","setup":["Hold one end of a dumbbell vertically against your chest with both hands, or hold a kettlebell by the horns.","Keep your elbows pointing down and close to the ribs.","Stand with feet slightly wider than shoulder width and toes turned out a little.","Brace your trunk and keep the weight against your chest."],"execution":["Push your hips back and bend your knees to sit down between your legs.","Keep your chest up and let your elbows move inside your knees at the bottom.","Lower until your thighs are at least parallel to the floor, or as deep as you can with a neutral spine.","Press through the whole foot to stand up, squeezing your glutes at the top.","Keep the weight against your chest for the entire set."],"cues":["Weight glued to the chest","Sit down between the knees","Tall chest, ribs down","Push the floor away"],"mistakes":["Letting the dumbbell drift away from the body and the torso fold forward: keep it pinned to your chest and elbows down.","Knees collapsing inward: push the knees out in line with the toes, using the elbows as a cue.","Heels lifting: place your weight on the midfoot and heel and widen the stance a bit.","Using a weight that is too heavy to hold: pick a load you can keep tight against the chest for all reps."],"default_sets":3,"default_reps":"8-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=nfX7IFK9UNI","title":"How to do a Goblet Squat  | Proper Form & Technique | NASM","author":"National Academy of Sports Medicine (NASM)","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=gm4ln6PO4rc","title":"How to PROPERLY Goblet Squat (FIX THIS NOW!)","author":"Colossus Fitness","checked":"2026-10-23"}]}'::jsonb),
('good-morning', 'Good Morning', 'hamstrings', 'barbell', 'compound', 'advanced', '{"slug":"good-morning","name":"Good Morning","aliases":["Barbell Good Morning"],"muscle_group":"hamstrings","secondary":["glutes","lower-back"],"equipment":"barbell","mechanic":"compound","level":"advanced","summary":"A hip-hinge exercise with a barbell on the upper back that trains the hamstrings, glutes and spinal muscles. It demands good bracing and is best done with light to moderate loads.","setup":["Set the bar on your upper back as for a squat and unrack it.","Take a step back and set your feet about shoulder width with a soft knee bend.","Take a breath, brace your trunk and set your shoulder blades together."],"execution":["Push your hips back while keeping your knees softly bent and your back flat.","Lower your torso until it is near parallel to the floor or you feel a stretch in your hamstrings.","Keep the bar stable on your back and your neck neutral.","Drive your hips forward and stand tall by squeezing your glutes.","Re-rack the bar carefully when finished."],"cues":["Hips back","Flat back, braced trunk","Squeeze the glutes to stand"],"mistakes":["Rounding the back: use less weight and reduce the depth.","Squatting the movement by bending the knees too much: keep a fixed soft knee angle and push the hips back.","Going too heavy: use a light load and build up slowly.","Looking up and craning the neck: keep your head in line with your spine."],"default_sets":3,"default_reps":"8-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=VkNcc0BQrpA","title":"Good Mornings - Barbell Good Morning Exercise","author":"Nick Tumminello - Trainer of Trainers","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=2k5W4PTlCDw","title":"Good Morning - OPEX Exercise Library","author":"OPEX Fitness","checked":"2026-10-23"}]}'::jsonb),
('hack-squat', 'Hack Squat', 'quads', 'machine', 'compound', 'intermediate', '{"slug":"hack-squat","name":"Hack Squat","aliases":["Machine Hack Squat"],"muscle_group":"quads","secondary":["glutes","hamstrings"],"equipment":"machine","mechanic":"compound","level":"intermediate","summary":"A machine squat performed on an angled sled with the back supported. It allows deep, stable quad-focused squatting with little demand on balance.","setup":["Step into the machine and place your shoulders under the pads with your back flat against the pad.","Set your feet about shoulder width apart, a little forward on the platform, with toes turned out slightly.","Hold the handles and release the safety stops.","Stand up to the start position without locking your knees hard."],"execution":["Brace your trunk and lower under control by bending your knees and hips.","Keep your whole foot on the platform and your knees tracking over your toes.","Descend until your thighs are at least parallel, or as deep as you can while keeping your back and hips on the pad.","Drive through the whole foot to return to the top, stopping just short of lockout.","Re-engage the safety stops when finished."],"cues":["Back flat on the pad","Knees over toes","Push through the whole foot","Control the descent"],"mistakes":["Heels lifting off the platform: move your feet slightly forward or higher on the plate.","Hips tucking under at the bottom as the lower back rounds: shorten the depth to where the pelvis stays on the pad.","Knees drifting inward: push them out in line with the toes and use a lighter load.","Bouncing at the bottom: pause briefly and drive up smoothly."],"default_sets":3,"default_reps":"8-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=hglQExHCM9Q","title":"Hack Squat Machine (Exercise Tutorial + Form Tips) | Team Evolve","author":"Vivian Ngo","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=-lAnEGH2blE","title":"How to Do the Hack Squat | Build Stronger Legs with Proper Form","author":"Physio Plus Fitness","checked":"2026-10-23"}]}'::jsonb),
('hanging-leg-raise', 'Hanging Leg Raise', 'abs', 'bodyweight', 'compound', 'intermediate', '{"slug":"hanging-leg-raise","name":"Hanging Leg Raise","aliases":["Hanging Knee Raise","Leg Raise"],"muscle_group":"abs","secondary":["forearms"],"equipment":"bodyweight","mechanic":"compound","level":"intermediate","summary":"A hanging exercise that trains the abs and hip flexors while building grip strength. Bend the knees to make it easier.","setup":["Hang from a pull-up bar with an overhand grip, shoulders pulled slightly down.","Keep the legs together and the body still.","Brace the abs before you move."],"execution":["Raise your knees or straight legs by curling the pelvis up toward the ribs.","Lift until the legs are at least parallel to the floor, or higher if you control it.","Pause, then lower the legs slowly without swinging.","Keep the shoulders active throughout."],"cues":["Curl the pelvis up","Control the swing","Slow lowering"],"mistakes":["Swinging the body: slow down and pause between reps.","Using only the hip flexors: tilt the pelvis up at the top.","Letting the shoulders shrug to the ears: keep the shoulders down and active.","Dropping the legs: lower slowly for 2-3 seconds."],"default_sets":3,"default_reps":"8-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=Pr1ieGZ5atk","title":"Hanging Leg Raise | HOW-TO","author":"ATHLEAN-X™","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=hdng3Nm1x_E","title":"How To: Hanging Leg-Lift","author":"ScottHermanFitness","checked":"2026-10-23"}]}'::jsonb),
('hollow-body-hold', 'Hollow Body Hold', 'abs', 'bodyweight', 'isolation', 'intermediate', '{"slug":"hollow-body-hold","name":"Hollow Body Hold","aliases":["Hollow Hold","Hollow Rock Position"],"muscle_group":"abs","secondary":["quads"],"equipment":"bodyweight","mechanic":"isolation","level":"intermediate","summary":"An isometric core hold with the lower back pressed down, a foundation for gymnastics and calisthenics.","setup":["Lie on your back with arms by your sides.","Press your lower back into the floor.","Lift shoulders and legs, keeping legs bent to make it easier."],"execution":["Raise your shoulders and legs off the floor.","Keep your lower back pressed down.","Extend your arms overhead and legs straight if you can keep the back flat.","Hold for the time, breathing steadily."],"cues":["Lower back glued down","Ribs to hips","Tuck the pelvis"],"mistakes":["Lower back lifting: bend the knees or raise the legs higher.","Holding the breath: breathe.","Neck strain: keep chin slightly tucked.","Going too long: stop when form fails."],"default_sets":3,"default_reps":"20-30 s","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=hf00_b2sRdc","title":"How to Perfect Your Hollow Hold | Form Check | Men''s Health","author":"Men''s Health","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=Xk-JcNj6lfY","title":"How To: Hollow Body Hold","author":"Summit Performance Club","checked":"2026-10-23"}]}'::jsonb),
('incline-barbell-bench-press', 'Incline Barbell Bench Press', 'chest', 'barbell', 'compound', 'intermediate', '{"slug":"incline-barbell-bench-press","name":"Incline Barbell Bench Press","aliases":["Incline Bench Press"],"muscle_group":"chest","secondary":["shoulders","triceps"],"equipment":"barbell","mechanic":"compound","level":"intermediate","summary":"A bench press on an inclined bench that shifts emphasis to the upper chest and front delts.","setup":["Set the bench to a modest incline of about 30 degrees; steeper angles shift work to the shoulders.","Lie back with eyes under the bar, feet flat, shoulder blades pulled back and down.","Grip slightly wider than shoulder width and unrack with straight arms.","Set the safety arms or use a spotter."],"execution":["Inhale, brace, and lower the bar under control to the upper chest.","Keep forearms near vertical and elbows about 45-70 degrees from the torso.","Press up until the arms are straight over the shoulders.","Rack the bar with control once the set is done."],"cues":["Shoulder blades pinned to the bench","Bar to upper chest","Stay tight, no bouncing"],"mistakes":["Bench set too steep: drop the angle so the chest, not just the shoulders, does the work.","Elbows flaring wide: tuck them to protect the shoulders.","Excess back arch and ribs flaring: keep glutes and upper back down on the pad.","Lowering to the neck: bring the bar to the upper chest instead."],"default_sets":3,"default_reps":"6-10","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=5kyLUGVq_pk","title":"How to PROPERLY Incline Barbell Bench Press (FIX YOUR FORM NOW)","author":"Colossus Fitness","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=11gY7Q5D5wo","title":"How to Do an Incline Barbell Bench Press","author":"LIVESTRONG","checked":"2026-10-23"}]}'::jsonb),
('incline-dumbbell-curl', 'Incline Dumbbell Curl', 'biceps', 'dumbbell', 'isolation', 'intermediate', '{"slug":"incline-dumbbell-curl","name":"Incline Dumbbell Curl","aliases":["Seated Incline Curl"],"muscle_group":"biceps","secondary":[],"equipment":"dumbbell","mechanic":"isolation","level":"intermediate","summary":"A curl performed on an incline bench so the arms start behind the torso, stretching the long head of the biceps. Use lighter weights than standing curls.","setup":["Set an adjustable bench to about 45-60 degrees and sit back with your head, shoulders and hips against the pad.","Hold a dumbbell in each hand and let the arms hang straight down, palms facing forward.","Plant your feet and keep the shoulder blades pressed lightly into the bench."],"execution":["Curl both dumbbells upward by bending the elbows, keeping the upper arms pointing down.","Squeeze at the top without letting the elbows move forward.","Lower slowly to a full stretch with the arms hanging.","Repeat for all reps without lifting the back from the bench."],"cues":["Let the arms hang behind the body","Elbows stay still","Full stretch at the bottom"],"mistakes":["Letting the elbows swing forward: keep the upper arms vertical so the stretch stays on the biceps.","Using too heavy a load and jerking the weights: choose a lighter pair and go slowly.","Lifting the shoulders off the pad: keep the back in contact with the bench.","Dropping the weights quickly from the top: control the lowering to protect the elbow and shoulder."],"default_sets":3,"default_reps":"8-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=DCe8f6vMe9A","title":"Stop Screwing Up Incline Dumbbell Curls (PROPER FORM!)","author":"ATHLEAN-X™","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=e3zNNfjJszA","title":"Incline Dumbbell Curl Form (How-To in 90 Seconds)","author":"Mike | J2FIT Strength & Conditioning","checked":"2026-10-23"}]}'::jsonb),
('incline-dumbbell-fly', 'Incline Dumbbell Fly', 'chest', 'dumbbell', 'isolation', 'intermediate', '{"slug":"incline-dumbbell-fly","name":"Incline Dumbbell Fly","aliases":["Incline Dumbbell Chest Fly","Incline DB Fly"],"muscle_group":"chest","secondary":["shoulders"],"equipment":"dumbbell","mechanic":"isolation","level":"intermediate","summary":"A fly performed on a slight incline to bias the upper chest through a long stretch.","setup":["Set the bench to about 30 degrees.","Sit with light dumbbells on your thighs, lie back and press them above the chest, palms facing each other.","Pull shoulder blades back and down, feet planted.","Slightly bend the elbows and keep that angle."],"execution":["Lower the dumbbells in a wide arc until you feel a stretch in the chest.","Keep the elbow bend fixed and wrists neutral.","Squeeze the chest to bring the dumbbells back over the upper chest.","Lower the weights carefully to your thighs when finished."],"cues":["Arc, not press","Soft elbows","Chest does the lifting"],"mistakes":["Dumbbells too heavy: reduce load and use full control.","Bench too steep: stay near 30 degrees so the chest is still involved.","Dropping the arms too low: stop at a comfortable stretch.","Turning it into a press by bending the elbows more: keep the angle constant."],"default_sets":3,"default_reps":"10-15","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=idAvu2HvqSQ","title":"HOW TO: Incline Dumbbell Fly || PERFECT FORM (GROWTH & STRENGTH)","author":"ScottHermanFitness","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=qOsyhGAesSM","title":"How To Do An INCLINE DUMBBELL FLY | Exercise Demonstration Video and Guide","author":"Live Lean TV Daily Exercises","checked":"2026-10-23"}]}'::jsonb),
('incline-dumbbell-press', 'Incline Dumbbell Press', 'chest', 'dumbbell', 'compound', 'beginner', '{"slug":"incline-dumbbell-press","name":"Incline Dumbbell Press","aliases":["Incline Dumbbell Bench Press","Incline DB Press"],"muscle_group":"chest","secondary":["shoulders","triceps"],"equipment":"dumbbell","mechanic":"compound","level":"beginner","summary":"A dumbbell press on an incline bench that emphasizes the upper chest with a flexible arm path.","setup":["Set the bench to about 30 degrees; avoid very steep angles that turn it into a shoulder press.","Sit with the dumbbells on your thighs, lie back and bring them to chest level.","Set shoulder blades back and down, feet planted firmly.","Start with palms facing forward or slightly angled in, wrists stacked over elbows."],"execution":["Press the dumbbells up and slightly together until the arms are straight.","Lower under control until the upper arms are about parallel to the floor.","Keep elbows about 45-70 degrees from the torso.","Bring the dumbbells back to your thighs before sitting up."],"cues":["Chest up, shoulder blades pinned","Press in a slight arc","Control the descent"],"mistakes":["Bench too steep: lower the angle so the chest keeps working.","Arching the lower back and flaring ribs: keep ribs down and glutes on the bench.","Flared elbows: tuck them slightly.","Weights too heavy to control: reduce load and keep the lowering slow."],"default_sets":3,"default_reps":"8-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=0G2_XV7slIg","title":"Grow Your Chest with the INCINE DUMBBELL PRESS | Mind Pump","author":"Mind Pump TV","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=oZVCBM9f8Eo","title":"How To Do A Dumbbell Incline Press","author":"PureGym","checked":"2026-10-23"}]}'::jsonb),
('incline-push-up', 'Incline Push-Up', 'chest', 'bodyweight', 'compound', 'beginner', '{"slug":"incline-push-up","name":"Incline Push-Up","aliases":["Elevated Push-Up","Hands-Elevated Push-Up"],"muscle_group":"chest","secondary":["triceps","shoulders","abs"],"equipment":"bodyweight","mechanic":"compound","level":"beginner","summary":"An easier push-up with the hands raised, ideal for learning the push-up pattern and building up to floor push-ups.","setup":["Place your hands on a sturdy bench, sofa arm, table or kitchen counter slightly wider than shoulder width.","Step your feet back until your body forms a straight line from head to heels.","Make sure the surface cannot slide, and brace abs and glutes."],"execution":["Lower your chest toward the edge of the surface with elbows at about 45 degrees.","Keep your body straight and neck neutral.","Press away to straighten your arms.","Use a lower surface to make it harder as you improve."],"cues":["Plank body","Elbows at 45 degrees","Chest to the edge"],"mistakes":["Hips sagging: squeeze glutes and brace the abs.","Elbows flaring wide: tuck them to about 45 degrees.","Using an unstable surface: pick a sturdy, non-slip one.","Short range: lower until the chest nearly touches the surface."],"default_sets":3,"default_reps":"10-15","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=yAbg3_pJKvw","title":"How To Do An Incline Push Up","author":"PureGym","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=Gvm5Q29UHbk","title":"How to do an Incline Push-Up","author":"National Academy of Sports Medicine (NASM)","checked":"2026-10-23"}]}'::jsonb),
('inverted-row', 'Inverted Row', 'back', 'bodyweight', 'compound', 'beginner', '{"slug":"inverted-row","name":"Inverted Row","aliases":["Bodyweight Row","Australian Pull-Up"],"muscle_group":"back","secondary":["lats","biceps","rear-delts","abs"],"equipment":"bodyweight","mechanic":"compound","level":"beginner","summary":"A bodyweight horizontal row under a fixed bar that trains the upper back and arms; difficulty is adjusted by body angle and foot position.","setup":["Set a bar at about waist to chest height, for example in a squat rack or Smith machine.","Lie underneath and grip the bar with an overhand grip slightly wider than shoulder width.","Extend the body in a straight line from head to heels, heels on the floor, arms straight."],"execution":["Squeeze the glutes and abs to keep the body rigid.","Pull the chest toward the bar by driving the elbows back.","Squeeze the shoulder blades together at the top.","Lower under control until the arms are straight."],"cues":["Body like a plank","Chest to the bar","Elbows at about 45 degrees"],"mistakes":["Sagging hips: squeeze the glutes and abs, or raise the bar to make it easier.","Reaching with the chin or neck: keep the head neutral and pull the chest up.","Short reps: finish with the chest touching the bar and arms fully extended at the bottom.","Too hard to complete reps: raise the bar or bend the knees."],"default_sets":3,"default_reps":"8-15","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=5LZa9TzkjRg","title":"Inverted Row Exercise - Best Form Tips!","author":"Nick Tumminello - Trainer of Trainers","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=hXTc1mDnZCw","title":"Inverted Row Guide | Form Tips, Muscles Worked, and Mistakes","author":"BarBend","checked":"2026-10-23"}]}'::jsonb),
('jump-squat', 'Jump Squat', 'quads', 'bodyweight', 'compound', 'intermediate', '{"slug":"jump-squat","name":"Jump Squat","aliases":["Squat Jump"],"muscle_group":"quads","secondary":["glutes","hamstrings","calves"],"equipment":"bodyweight","mechanic":"compound","level":"intermediate","summary":"An explosive squat variation that adds a jump to train power in the legs and raise your heart rate.","setup":["Stand with feet shoulder width apart on a non-slip surface with room around you.","Hold your hands in front of your chest or let them swing freely.","Brace your abs and keep your chest tall."],"execution":["Squat down to about parallel by sending your hips back.","Drive through your feet and jump up explosively, extending hips, knees and ankles.","Land softly on the middle of your feet with knees slightly bent.","Absorb the landing by sinking straight into the next squat."],"cues":["Sit, then explode","Land soft and quiet","Knees in line with toes"],"mistakes":["Landing stiff-legged: bend your hips and knees to absorb the impact and aim for a quiet landing.","Knees collapsing inward on landing: focus on pushing them out over the toes or reduce the jump height.","Shallow squat before the jump: sink to a consistent depth each rep.","Training while very tired: stop the set when landings become sloppy."],"default_sets":3,"default_reps":"8-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=BRfxI2Es2lE","title":"How To Jump Squat","author":"PureGym","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=A-cFYWvaHr0","title":"How To Do A Squat Jump | The Right Way | Well+Good","author":"Well+Good","checked":"2026-10-23"}]}'::jsonb),
('kettlebell-swing', 'Kettlebell Swing', 'glutes', 'kettlebell', 'compound', 'intermediate', '{"slug":"kettlebell-swing","name":"Kettlebell Swing","aliases":["Russian Kettlebell Swing","Two-Hand Kettlebell Swing"],"muscle_group":"glutes","secondary":["hamstrings","lower-back","abs","shoulders"],"equipment":"kettlebell","mechanic":"compound","level":"intermediate","summary":"An explosive hip hinge that swings a kettlebell to chest height using hip power. It builds the glutes and hamstrings and conditioning. A dumbbell held by one end can replace the kettlebell.","setup":["Place a kettlebell about a foot in front of you. A dumbbell held vertically by one end also works.","Stand with feet slightly wider than shoulder width and toes slightly out.","Hinge your hips back, keep your back flat, and grab the handle with both hands.","Hike the kettlebell back between your legs, with the forearms against your thighs."],"execution":["Drive your hips forward explosively, squeezing your glutes, and let the kettlebell float up to chest height.","Keep your arms relaxed as hooks, since the hips make the weight move.","Stand tall at the top with ribs down and glutes tight.","Let the bell fall and hinge your hips back as it swings between your legs, then repeat."],"cues":["Hinge, don''t squat","Snap the hips","Arms are just ropes","Stand tall, glutes tight"],"mistakes":["Squatting the swing: push the hips back and keep the shins nearly vertical.","Lifting with the arms and shoulders: let the hips power it and keep arms loose.","Leaning back at the top: finish with a tall, braced stance and ribs down.","Rounding the back at the bottom: keep the chest up and hinge from the hips, and use a lighter weight."],"default_sets":4,"default_reps":"10-15","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=aSYap2yhW8s","title":"The BEST Kettlebell Swing Tutorial","author":"Squat University","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=bDCeXbMJVNs","title":"How To Kettlebell Swing (in 3 minutes)","author":"Zack Henderson","checked":"2026-10-23"}]}'::jsonb),
('lateral-lunge', 'Lateral Lunge', 'quads', 'bodyweight', 'compound', 'beginner', '{"slug":"lateral-lunge","name":"Lateral Lunge","aliases":["Side Lunge","Side-to-Side Lunge"],"muscle_group":"quads","secondary":["glutes","hamstrings"],"equipment":"bodyweight","mechanic":"compound","level":"beginner","summary":"A side-stepping lunge that trains the legs and glutes in the frontal plane and builds hip mobility.","setup":["Stand tall with feet together, hands clasped at your chest.","Brace your abs and look straight ahead.","Make sure you have space to step to the side."],"execution":["Take a big step to the side with one foot, toes pointing forward.","Push your hips back and bend the stepping knee, keeping the other leg straight.","Keep the stepping foot flat and your chest up as you lower.","Push through the bent leg to return to the start.","Complete the reps on one side, then switch."],"cues":["Hips back, chest up","Both feet point forward","Push the floor away"],"mistakes":["Heel of the working foot lifting: sit back into the hips and take a slightly shorter step.","Rounding the back: keep the chest up and reduce depth.","Knee drifting inside the foot: track it in line with the toes.","Toes turning out too far: keep both feet pointing forward."],"default_sets":3,"default_reps":"8-12 per side","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=vwK7vZNQwUI","title":"Lateral lunge - how to do it right.","author":"Revival Performance Physical Therapy","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=K_NEjwxkF7k","title":"Lateral Lunge","author":"Orillia Sports Medicine And Rehabilitation","checked":"2026-10-23"}]}'::jsonb),
('leg-extension', 'Leg Extension', 'quads', 'machine', 'isolation', 'beginner', '{"slug":"leg-extension","name":"Leg Extension","aliases":["Machine Leg Extension","Seated Leg Extension"],"muscle_group":"quads","secondary":[],"equipment":"machine","mechanic":"isolation","level":"beginner","summary":"A machine isolation exercise for the quadriceps that lets you load the front of the thigh directly with little help from other muscles.","setup":["Adjust the seat so your knees line up with the machine''s pivot point and your back is supported.","Set the pad on your lower shins just above the ankles.","Adjust the back pad so the edge of the seat sits a few finger widths behind your knees.","Hold the handles and choose a weight you can control."],"execution":["Extend your knees to lift the pad until your legs are almost straight.","Squeeze your quads for a moment at the top.","Lower the pad slowly, taking about two to three seconds, until your knees are bent to roughly 90 degrees.","Keep your hips in the seat and avoid swinging the weight.","Repeat for the set and lower the weight stack gently."],"cues":["Squeeze the quads at the top","Slow on the way down","Hips glued to the seat"],"mistakes":["Swinging the weight with momentum: reduce the load and use a controlled tempo.","Hips lifting out of the seat as you reach the top: lower the weight and hold the handles or re-set the back pad.","Cutting the range short: use the full range you can control.","Slamming the weight stack at the bottom: lower slowly and stop short of resting the stack."],"default_sets":3,"default_reps":"10-15","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=3zWKiW9BBpo","title":"How to Do Leg Extensions with Perfect Form (The Proper Range of Motion)","author":"Cris Edmonds TV","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=Cy9TJ_jhEBs","title":"How to Use the Leg Extension Machine | Exercise with PartnerMD","author":"PartnerMD","checked":"2026-10-23"}]}'::jsonb),
('leg-press', 'Leg Press', 'quads', 'machine', 'compound', 'beginner', '{"slug":"leg-press","name":"Leg Press","aliases":["45-Degree Leg Press","Machine Leg Press"],"muscle_group":"quads","secondary":["glutes","hamstrings"],"equipment":"machine","mechanic":"compound","level":"beginner","summary":"A machine press that loads the quads and glutes with the back supported, so you can train the legs hard with little demand on balance or the trunk.","setup":["Adjust the seat so your knees are bent at about 90 degrees or a little more when the sled is at the bottom.","Sit with your back and hips flat against the pad and place your feet about shoulder width on the platform, mid-height.","Grip the handles and unlock the safety handles or stops as shown on your machine.","Press the sled up to a near-straight leg position to start, without locking out."],"execution":["Take a breath and lower the sled slowly by bending your knees and hips.","Stop when your knees are at about 90 degrees or when your hips are about to lift off the pad.","Keep your whole foot on the platform and your knees tracking in line with your toes.","Press the platform away, exhaling, until your legs are almost straight.","Re-lock the safety stops before getting out of the machine."],"cues":["Hips and back stay on the pad","Control down, push up","Knees follow toes","Stop just short of lockout"],"mistakes":["Lowering too deep so the hips curl off the pad and the lower back rounds: limit the range to where the pelvis stays flat.","Locking the knees hard at the top: stop just short of full lockout and keep tension on the muscles.","Knees caving in: push the knees out toward the little toes and lighten the weight.","Bouncing out of the bottom with a heavy load: slow down and use a weight you can control."],"default_sets":3,"default_reps":"8-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=cDGOn-yfKJA","title":"How to do a Leg Press  | Proper Form & Technique | NASM","author":"National Academy of Sports Medicine (NASM)","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=K5n2vg3oZa4","title":"How to PROPERLY Leg Press (FIX YOUR FORM NOW)","author":"Colossus Fitness","checked":"2026-10-23"}]}'::jsonb),
('lying-leg-curl', 'Lying Leg Curl', 'hamstrings', 'machine', 'isolation', 'beginner', '{"slug":"lying-leg-curl","name":"Lying Leg Curl","aliases":["Prone Leg Curl","Lying Hamstring Curl"],"muscle_group":"hamstrings","secondary":["calves"],"equipment":"machine","mechanic":"isolation","level":"beginner","summary":"A machine isolation exercise that trains the hamstrings through knee flexion while you lie face down.","setup":["Adjust the machine so your knees line up with the pivot and the pad sits just above your ankles.","Lie face down with your hips flat on the bench and hold the handles.","Pick a weight you can curl without lifting your hips."],"execution":["Curl your heels toward your glutes by bending your knees.","Squeeze your hamstrings at the top without letting your hips rise.","Lower the pad slowly over two to three seconds until your legs are almost straight.","Keep your hips pressed into the bench and avoid jerking the weight.","Repeat for the set."],"cues":["Heels to glutes","Hips pressed down","Slow on the way down"],"mistakes":["Hips lifting off the bench: lighten the load and press your hips down.","Using momentum to swing the weight up: slow down and use a controlled tempo.","Cutting the lowering phase short: lower under control to nearly full extension.","Pad set too high on the calves: move it just above the ankles."],"default_sets":3,"default_reps":"10-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=lUH80pneL5w","title":"How to do a Lying Leg Curl | Proper Form & Technique | NASM","author":"National Academy of Sports Medicine (NASM)","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=SbSNUXPRkc8","title":"How To Do A Lying Leg Curl (Prone Leg Curl)","author":"PureGym","checked":"2026-10-23"}]}'::jsonb),
('lying-leg-raise', 'Lying Leg Raise', 'abs', 'bodyweight', 'isolation', 'beginner', '{"slug":"lying-leg-raise","name":"Lying Leg Raise","aliases":["Leg Raise","Flat Leg Raise"],"muscle_group":"abs","secondary":["quads"],"equipment":"bodyweight","mechanic":"isolation","level":"beginner","summary":"A floor exercise for the lower abs and hip flexors that needs only a mat.","setup":["Lie on your back with legs straight and arms by your sides, or hands under your hips.","Press your lower back toward the floor.","Brace your abs."],"execution":["Raise your legs together until they point up toward the ceiling.","Lower them slowly without letting the lower back arch.","Stop just above the floor and repeat.","Bend the knees slightly to make it easier."],"cues":["Back flat","Slow on the way down","Brace the abs"],"mistakes":["Arching the lower back: bend the knees or lower less.","Swinging the legs: use a slow tempo.","Holding the breath: exhale as you lift.","Neck tension: keep the head relaxed on the floor."],"default_sets":3,"default_reps":"8-15","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=3oIpxsn6FxQ","title":"Perfect Lying Leg Raises Form to Strengthen Your Core & Avoid Back Pain","author":"Mobility Doc","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=xJJu-WiROM8","title":"How To Perform The Lying Leg Raise Exercise","author":"Dimitri Giankoulas","checked":"2026-10-23"}]}'::jsonb),
('lying-triceps-extension', 'Lying Triceps Extension', 'triceps', 'ez-bar', 'isolation', 'intermediate', '{"slug":"lying-triceps-extension","name":"Lying Triceps Extension","aliases":["Skull Crusher","French Press","Lying Triceps Press"],"muscle_group":"triceps","secondary":[],"equipment":"ez-bar","mechanic":"isolation","level":"intermediate","summary":"An isolation lift where the elbows bend and extend over the head or forehead while lying down, targeting all heads of the triceps.","setup":["Lie on a flat bench holding an EZ bar with a shoulder-width, palms-forward grip.","Press the bar over your chest with arms straight, then tilt it slightly back over the head.","Pin the upper arms vertical or angled slightly back.","Choose a weight you can fully control near your face; use a spotter if heavy."],"execution":["Lower the bar by bending only at the elbows, toward the forehead or just behind the head.","Keep upper arms still and elbows pointing to the ceiling.","Extend the elbows to press the bar back up.","Finish with a firm triceps squeeze at the top."],"cues":["Elbows fixed","Bar slightly behind the head","Slow and controlled"],"mistakes":["Elbows flaring wide: keep them narrow and pointing up.","Using momentum from the shoulders: reduce weight and move only at the elbows.","Dropping the weight near the face: lower slowly and never rush the bottom.","Wrists bending painfully: use an EZ bar or switch to dumbbells."],"default_sets":3,"default_reps":"8-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=4re6CJ0XNF8","title":"How To Do The Lying Triceps Extension Exercise |  Jim Stoppani, Ph.D.","author":"Bodybuilding.com","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=p1sJ84EmFD4","title":"Lying Skull Crushers For Huge Triceps (The Exercise You Need to be Doing‼️)","author":"Cris Edmonds TV","checked":"2026-10-23"}]}'::jsonb),
('meadows-row', 'Meadows Row', 'back', 'barbell', 'compound', 'intermediate', '{"slug":"meadows-row","name":"Meadows Row","aliases":["Landmine Meadows Row"],"muscle_group":"back","secondary":["lats","rear-delts","biceps","traps"],"equipment":"barbell","mechanic":"compound","level":"intermediate","summary":"A single-arm landmine row, named after John Meadows, performed side-on to the bar for a deep stretch and strong contraction in the lats and mid back.","setup":["Anchor a barbell in a landmine or corner and load the free end.","Stand perpendicular to the bar, hinge at the hips and grip the thick end of the bar near the plates with an overhand grip.","Rest your free hand on your thigh or a support to stay stable with a flat back."],"execution":["Pull the elbow up and back toward your hip.","Squeeze the shoulder blade toward the spine at the top.","Lower until the arm is straight, allowing a stretch at the bottom.","Finish all reps, then switch sides."],"cues":["Elbow to the back pocket","Keep hips and shoulders square","Own the stretch"],"mistakes":["Rotating the torso: use less load and brace the abs.","Rounding the back: keep a long spine and a proud chest.","Using only the biceps: lead with the elbow.","Pulling too high toward the shoulder: pull toward the hip."],"default_sets":3,"default_reps":"8-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=bTCx4NuySDs","title":"Meadows Row: Fixing Your Form","author":"Cris Edmonds TV","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=G-jU1aPVhnY","title":"How to Meadows Row \"The Right Way\"","author":"mountaindog1","checked":"2026-10-23"}]}'::jsonb),
('mountain-climber', 'Mountain Climber', 'abs', 'bodyweight', 'compound', 'beginner', '{"slug":"mountain-climber","name":"Mountain Climber","aliases":["Running Plank"],"muscle_group":"abs","secondary":["shoulders","quads"],"equipment":"bodyweight","mechanic":"compound","level":"beginner","summary":"A dynamic plank exercise that trains the trunk and shoulders while driving the knees in alternation for conditioning.","setup":["Start in a high plank with hands under shoulders.","Form a straight line from head to heels.","Brace your abs and squeeze glutes.","Place hands on a low sturdy bench to make it easier."],"execution":["Drive one knee toward your chest.","Switch legs, returning one foot back as the other comes forward.","Keep hips level and shoulders over hands.","Alternate at a pace you can control."],"cues":["Plank first","Hips level","Knees to chest"],"mistakes":["Hips bouncing up: lower them to a straight line and slow down.","Hands drifting forward: keep them under the shoulders.","Rounding the back: brace abs.","Rushing with short steps: take a full range of motion at a controlled pace."],"default_sets":3,"default_reps":"20-40 s","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=cnyTQDSE884","title":"How to Do Mountain Climbers | The Right Way | Well+Good","author":"Well+Good","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=fpmWW6iXfes","title":"Proper Mountain Climber Form (Fix Your Form!)","author":"Live Lean TV","checked":"2026-10-23"}]}'::jsonb),
('neck-flexion-band', 'Neck Flexion with Band', 'neck', 'band', 'isolation', 'beginner', '{"slug":"neck-flexion-band","name":"Neck Flexion with Band","aliases":["Banded Neck Flexion"],"muscle_group":"neck","secondary":[],"equipment":"band","mechanic":"isolation","level":"beginner","summary":"A gentle neck exercise that uses a resistance band to train the muscles at the front of the neck. A good low-load starting point for neck training.","setup":["Anchor a light band at head height and loop it around your forehead or hold it against the forehead.","Face away from the anchor, stand tall and step forward until the band has light tension.","Keep the shoulders relaxed and the chin slightly tucked."],"execution":["Slowly nod the head forward against the band''s pull.","Pause briefly, then return to neutral in control.","Keep the movement small and smooth.","Repeat for 10-15 reps. Stop if you feel dizzy, numb or sharp pain."],"cues":["Slow and smooth","Light tension","Stop if dizzy or numb"],"mistakes":["Using a band that is too strong: choose very light tension.","Letting the shoulders hike up: relax the shoulders and stand tall.","Jerking the head forward: move slowly through a small range.","Holding the breath: breathe steadily."],"default_sets":2,"default_reps":"10-15","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=mgT8eT6oSMM","title":"Banded Neck Flexion","author":"Physio Brad","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=-4ZXyLnxIPk","title":"Resistance Band Neck Flexion","author":"Coach Wayland","checked":"2026-10-23"}]}'::jsonb),
('neck-flexion-extension-plate-or-harness', 'Neck Flexion and Extension (Plate or Harness)', 'neck', 'other', 'isolation', 'intermediate', '{"slug":"neck-flexion-extension-plate-or-harness","name":"Neck Flexion and Extension (Plate or Harness)","aliases":["Weighted Neck Flexion","Neck Harness Extension"],"muscle_group":"neck","secondary":[],"equipment":"other","mechanic":"isolation","level":"intermediate","summary":"Loaded neck flexion and extension using a plate or a neck harness to strengthen the muscles at the front and back of the neck. Keep the load very light and the movement slow.","setup":["Start with very light weight or just a folded towel and plate, well below what you think you can handle.","Sit or lie on a bench with a stable position and a neutral spine.","Attach the harness or place the plate carefully, with a spotter or hands ready if needed.","Warm up the neck with gentle movement first."],"execution":["Lower the head slowly through a small, comfortable range.","Raise the head back to neutral, keeping the movement slow and controlled.","Pause briefly, then repeat for 10-15 reps with strict control.","Add weight in tiny steps, only when every rep is smooth and pain-free. Stop at once if you feel dizzy, numb, tingling or sharp pain."],"cues":["Light, slow and controlled","Small increases only","Stop if dizzy or numb"],"mistakes":["Using too much weight too soon: begin with very light loads and progress gradually over weeks.","Jerking or bouncing the head: use a slow tempo.","Going into extreme range: stay within a comfortable range.","Ignoring warning signs such as dizziness, numbness or tingling: stop the exercise immediately and consult a professional."],"default_sets":2,"default_reps":"10-15","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=2KHF3sQbyOQ","title":"Do''s and Dont''s of Neck Strengthening","author":"Stephan Kesting","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=e0PyIvz7--U","title":"How to Use Head Harness | Neck Training | DMoose","author":"DMoose","checked":"2026-10-23"}]}'::jsonb),
('one-arm-dumbbell-row', 'One-Arm Dumbbell Row', 'back', 'dumbbell', 'compound', 'beginner', '{"slug":"one-arm-dumbbell-row","name":"One-Arm Dumbbell Row","aliases":["Single-Arm Dumbbell Row","Dumbbell Row"],"muscle_group":"back","secondary":["lats","biceps","rear-delts","forearms"],"equipment":"dumbbell","mechanic":"compound","level":"beginner","summary":"A supported unilateral row that lets you load each side of the back with a long range of motion and minimal lower-back demand.","setup":["Place one hand and the same-side knee on a flat bench, or one hand on the bench with the other foot back.","Keep the back flat and roughly parallel to the floor.","Hold the dumbbell with a neutral grip and arm hanging straight below the shoulder."],"execution":["Pull the dumbbell toward your hip, leading with the elbow.","Squeeze the shoulder blade toward the spine at the top.","Lower until the arm is straight and the shoulder blade stretches forward.","Finish all reps, then switch sides."],"cues":["Elbow to the hip","Chest and hips square to the floor","Control the lowering"],"mistakes":["Twisting the torso to lift: keep the shoulders level and use a lighter weight.","Pulling straight up to the chest: row toward the hip in a slight arc.","Rounding the back: keep the spine long and the head in line with it.","Short range of motion: stretch fully at the bottom before each pull."],"default_sets":3,"default_reps":"8-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=gfUg6qWohTk","title":"STOP F*cking Up Dumbbell Rows (PROPER FORM!)","author":"ATHLEAN-X™","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=nYFjVJqMmM8","title":"How To Do The Single Arm Dumbbell Row | Avoid Common Mistakes For Less Shoulder And Neck Pain","author":"Dr. Carl Baird","checked":"2026-10-23"}]}'::jsonb),
('overhead-dumbbell-triceps-extension', 'Overhead Dumbbell Triceps Extension', 'triceps', 'dumbbell', 'isolation', 'beginner', '{"slug":"overhead-dumbbell-triceps-extension","name":"Overhead Dumbbell Triceps Extension","aliases":["Overhead Triceps Extension","Dumbbell French Press"],"muscle_group":"triceps","secondary":[],"equipment":"dumbbell","mechanic":"isolation","level":"beginner","summary":"A triceps isolation exercise with the arms overhead, which stretches the long head of the triceps.","setup":["Sit on a bench with back support or stand tall, holding one dumbbell with both hands.","Press the dumbbell overhead with arms straight, palms under the top plate.","Keep ribs down and core braced, avoiding a big back arch.","Keep upper arms close to the head, pointing up."],"execution":["Bend the elbows to lower the dumbbell behind the head until you feel a triceps stretch.","Keep the upper arms still and elbows pointing forward.","Extend the elbows to return to the top.","Squeeze the triceps at lockout."],"cues":["Elbows in and up","Only the forearms move","Full stretch, full lockout"],"mistakes":["Elbows flaring out wide: keep them pointing forward.","Arching the lower back: brace the core and lower the weight.","Going too heavy, causing shoulder or elbow strain: use a controlled load.","Partial range of motion: lower until you feel a stretch."],"default_sets":3,"default_reps":"10-15","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=fYqswDVbJDg","title":"HOW TO: Overhead Triceps Extension (BEST EXERCISE FOR HUGE TRICEPS) || PERFECT FORM (POWERBOMB)","author":"ScottHermanFitness","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=xbNm9fRoUTw","title":"Dumbbell Overhead Tricep Extension | Olympic Weightlifting Exercise Library","author":"Catalyst Athletics","checked":"2026-10-23"}]}'::jsonb),
('pallof-press', 'Pallof Press', 'abs', 'cable', 'isolation', 'beginner', '{"slug":"pallof-press","name":"Pallof Press","aliases":["Cable Pallof Press","Band Pallof Press"],"muscle_group":"abs","secondary":["shoulders"],"equipment":"cable","mechanic":"isolation","level":"beginner","summary":"An anti-rotation press that trains the abs and obliques to resist twisting. Works with a cable machine or a resistance band.","setup":["Set a cable or band at chest height and stand sideways to the anchor.","Hold the handle at your chest with both hands.","Step away until there is tension and set your feet shoulder-width apart."],"execution":["Brace the abs and press the handle straight out in front of the chest.","Hold briefly with the arms extended while resisting the pull.","Bring the handle back to the chest under control.","Complete all reps, then switch sides."],"cues":["Do not let the torso twist","Hips and shoulders square","Slow press"],"mistakes":["Rotating toward the anchor: lighten the load and keep the shoulders square.","Leaning away: stand tall and keep the ribs down.","Rushing the reps: slow the tempo.","Standing too close to the anchor: step away until the pull is challenging."],"default_sets":3,"default_reps":"10-12 per side","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=ma2OjgP5XDc","title":"Cable Pallof Press","author":"Warbird Academy","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=nFspBRHke4w","title":"Pallof Press","author":"StKatesAthletics","checked":"2026-10-23"}]}'::jsonb),
('pike-push-up', 'Pike Push-Up', 'shoulders', 'bodyweight', 'compound', 'intermediate', '{"slug":"pike-push-up","name":"Pike Push-Up","aliases":["Pike Press","Downward Dog Push-Up"],"muscle_group":"shoulders","secondary":["triceps","chest"],"equipment":"bodyweight","mechanic":"compound","level":"intermediate","summary":"A bodyweight vertical press in an inverted V position that trains the shoulders and triceps, and prepares you for handstand push-ups.","setup":["Start on hands and feet with your hips high so your body forms an inverted V.","Place hands about shoulder width apart and feet hip to shoulder width apart.","Keep your arms and legs nearly straight and your head between your arms.","For an easier version, raise your feet less or put your hands on a low step."],"execution":["Bend your elbows and lower the top of your head toward the floor between your hands.","Keep your elbows at roughly 45 degrees from your body.","Pause just above the floor, then press the floor away to return to the start.","Keep your hips high throughout the rep."],"cues":["Hips high","Head between the arms","Press the floor away"],"mistakes":["Hips dropping so it becomes a regular push-up: walk the feet closer and lift the hips.","Elbows flaring wide: keep them at about 45 degrees.","Bouncing off the head: lower under control and stop above the floor.","Too hard to complete reps: raise the hands on a sturdy chair or step to reduce load."],"default_sets":3,"default_reps":"6-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=XckEEwa1BPI","title":"How to do a Pike Push-Up","author":"National Academy of Sports Medicine (NASM)","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=fXgou2W10ok","title":"How to Pike Push Up | Beginner (Progressions)","author":"The Bodyweight Process","checked":"2026-10-23"}]}'::jsonb),
('plank', 'Plank', 'abs', 'bodyweight', 'isolation', 'beginner', '{"slug":"plank","name":"Plank","aliases":["Forearm Plank","Front Plank"],"muscle_group":"abs","secondary":["lower-back","shoulders"],"equipment":"bodyweight","mechanic":"isolation","level":"beginner","summary":"A static hold that trains the abs and trunk to resist sagging, building core stability for many other lifts.","setup":["Lie face down and place the forearms on the floor with elbows under the shoulders.","Extend the legs behind you with toes on the floor.","Lift the body so it forms a straight line from head to heels."],"execution":["Squeeze the glutes and brace the abs as if preparing for a light punch.","Keep the neck neutral and look at the floor between the hands.","Hold the position while breathing steadily.","Lower to the floor under control when form breaks."],"cues":["Straight line head to heels","Squeeze glutes and abs","Keep breathing"],"mistakes":["Sagging hips: squeeze the glutes and shorten the hold.","Hips piked high: lower them until the body is in a straight line.","Holding the breath: breathe slowly and steadily.","Looking forward and lifting the head: keep the neck in line with the spine."],"default_sets":3,"default_reps":"30-60 s","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=kL_NJAkCQBg","title":"Mastering the Plank - In Just 2 Minutes","author":"Calisthenicmovement","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=6LqqeBtFn9M","title":"How to do the perfect PLANK: technique and common mistakes","author":"Get Exercise Confident","checked":"2026-10-23"}]}'::jsonb),
('plate-pinch-hold', 'Plate Pinch Hold', 'forearms', 'other', 'isolation', 'beginner', '{"slug":"plate-pinch-hold","name":"Plate Pinch Hold","aliases":["Plate Pinch","Pinch Grip Hold"],"muscle_group":"forearms","secondary":[],"equipment":"other","mechanic":"isolation","level":"beginner","summary":"A static hold that trains the thumb and finger pinch grip by holding weight plates together smooth side out.","setup":["Stack two light plates with the smooth sides facing out.","Stand with your arm at your side and pinch the plates between your fingers and thumb.","Keep the wrist neutral and shoulders relaxed."],"execution":["Lift the plates off the floor or bench by pinching them together.","Hold them at your side for the target time.","Keep the wrist neutral and breathe normally.","Lower the plates under control and rest before the next set."],"cues":["Squeeze with thumb and fingers","Wrist straight","Hold for time"],"mistakes":["Using too heavy a stack: start light so you can hold for the full time.","Letting the wrist bend: keep it in line with the forearm.","Shrugging the shoulder: keep it relaxed.","Dropping the plates: lower them under control to protect your fingers and toes."],"default_sets":3,"default_reps":"20-30 s","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=rEJx6pLbTwE","title":"Plate Pinch Hold","author":"Dr. Bridger Cutler, DC, MS","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=jFTV3DQf3HE","title":"How To Do Plate Pinches","author":"PureGym","checked":"2026-10-23"}]}'::jsonb),
('preacher-curl', 'Preacher Curl (EZ-Bar)', 'biceps', 'ez-bar', 'isolation', 'beginner', '{"slug":"preacher-curl","name":"Preacher Curl (EZ-Bar)","aliases":["EZ-Bar Preacher Curl","Scott Curl"],"muscle_group":"biceps","secondary":[],"equipment":"ez-bar","mechanic":"isolation","level":"beginner","summary":"An EZ-bar curl with the upper arms supported on a sloped pad, which prevents cheating and keeps all the work on the biceps. This entry covers the EZ-bar version; the machine version follows the same technique.","setup":["Adjust the seat so your armpits rest at the top of the pad and the upper arms lie flat on it.","Take the EZ bar with an underhand grip, hands about shoulder-width apart.","Start with the arms almost fully extended and the chest against the pad."],"execution":["Curl the bar up toward your shoulders without lifting the elbows off the pad.","Squeeze the biceps at the top.","Lower the bar slowly until the arms are nearly straight, stopping just short of a hard lockout.","Keep the wrists straight throughout."],"cues":["Armpits against the pad","Slow and controlled on the way down","Stop short of a hard lockout"],"mistakes":["Bouncing out of the bottom: lower slowly and stop with a slight elbow bend to protect the elbow.","Lifting the elbows or hips off the bench: lower the weight and keep contact with the pad.","Using too much weight: pick a load you can lower under control.","Bending the wrists: keep them in line with the forearms."],"default_sets":3,"default_reps":"8-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=As2vHQ09NB0","title":"EZ Bar Preacher Curl - Exercise Tutorial","author":"James Harrison","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=Gydpcouclx8","title":"Conquer the EZ-Bar Preacher Curl, Max Out Your Biceps","author":"Men''s Health","checked":"2026-10-23"}]}'::jsonb),
('pull-up', 'Pull-Up', 'lats', 'bodyweight', 'compound', 'intermediate', '{"slug":"pull-up","name":"Pull-Up","aliases":["Pullup","Overhand Pull-Up"],"muscle_group":"lats","secondary":["biceps","back","forearms","abs"],"equipment":"bodyweight","mechanic":"compound","level":"intermediate","summary":"A bodyweight vertical pull with an overhand grip that builds the lats, upper back and arms. A benchmark of relative upper-body strength.","setup":["Grab the bar with an overhand grip, slightly wider than shoulder width.","Hang with arms fully extended, ribs down and glutes lightly squeezed.","Cross or bend the legs behind you so they do not swing."],"execution":["Start by pulling the shoulder blades down and back.","Drive the elbows down toward your ribs until your chin clears the bar.","Pause briefly with the chest high and the body in a straight line.","Lower under control until the arms are fully straight again."],"cues":["Elbows to ribs","Chest to the bar","Lower in 2-3 seconds"],"mistakes":["Kipping or swinging: brace the abs and glutes and slow each rep down.","Half reps from a bent-arm start: begin every rep from a full hang.","Craning the neck over the bar: keep the head neutral and bring the bar to you.","Shrugging the shoulders to the ears: pull the shoulder blades down before bending the elbows."],"default_sets":3,"default_reps":"5-10","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=rmdn5X_KLkY","title":"The PERFECT Pull-Up (Full Guide)","author":"SaturnoMovement","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=sIvJTfGxdFo","title":"The Official Pull-Up Checklist (AVOID MISTAKES!)","author":"ATHLEAN-X™","checked":"2026-10-23"}]}'::jsonb),
('push-up', 'Push-Up', 'chest', 'bodyweight', 'compound', 'beginner', '{"slug":"push-up","name":"Push-Up","aliases":["Press-Up","Pushup"],"muscle_group":"chest","secondary":["triceps","shoulders","abs"],"equipment":"bodyweight","mechanic":"compound","level":"beginner","summary":"A bodyweight press that trains the chest, shoulders, triceps and trunk, scalable by changing the hand height or adding load.","setup":["Place hands on the floor slightly wider than shoulder width, fingers spread.","Extend your legs behind you, feet together or hip-width.","Squeeze glutes and brace abs so the body forms a straight line from head to heels.","Position hands under the shoulders or slightly lower; screw them into the floor."],"execution":["Lower your body as one unit, elbows about 45 degrees from the torso.","Touch the chest close to the floor while keeping the body straight.","Push the floor away to return to the start.","Keep the neck neutral, looking slightly ahead of the hands."],"cues":["Plank body, elbows at 45 degrees","Push the floor away","Chest to the floor"],"mistakes":["Hips sagging or piking: squeeze glutes and brace the abs, or elevate the hands.","Elbows flared to 90 degrees: tuck them to about 45 degrees.","Partial range of motion: lower until the chest is near the floor or use an incline to keep full range.","Head dropping forward: keep the neck in line with the spine."],"default_sets":3,"default_reps":"8-15","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=i9sTjhN4Z3M","title":"The RIGHT Way To Do Push-Ups (PERFECT FORM)","author":"Mind Pump TV","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=rruHM_sB2Hc","title":"How To Do The Perfect Push Up","author":"CHRIS HERIA","checked":"2026-10-23"}]}'::jsonb),
('rack-pull', 'Rack Pull', 'back', 'barbell', 'compound', 'intermediate', '{"slug":"rack-pull","name":"Rack Pull","aliases":["Block Pull","Partial Deadlift"],"muscle_group":"back","secondary":["traps","glutes","hamstrings","lower-back","forearms"],"equipment":"barbell","mechanic":"compound","level":"intermediate","summary":"A deadlift from pins or blocks around knee height that loads the upper back, traps and hips with heavy weights and a shorter range.","setup":["Set the safety pins so the bar rests just below or at knee height.","Stand with the bar over mid-foot, hinge down and grip just outside the legs.","Pull the slack out of the bar, set the shoulder blades down and brace with a flat back."],"execution":["Push the floor away and drive the hips forward.","Keep the bar close to the legs as you stand tall.","Squeeze the glutes and upper back at lockout without leaning back.","Lower the bar under control back to the pins."],"cues":["Chest up, lats tight","Bar drags up the legs","Stand tall, do not lean back"],"mistakes":["Rounding the back: lower the weight and brace before every pull.","Hitching the bar up the thighs or leaning back at lockout: finish by squeezing the glutes only.","Bar drifting away from the body: keep it in contact with the legs.","Dropping the bar on the pins: control the descent."],"default_sets":3,"default_reps":"4-8","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=IZjW_8R9UYE","title":"How To Rack Pull - Increase Your DEADLIFT!","author":"Barbell Logic","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=aAjN8zS7Idg","title":"Rack Pulls | Lower Back | How-To Exercise Tutorial","author":"Buff Dudes Workouts","checked":"2026-10-23"}]}'::jsonb),
('resistance-band-row', 'Resistance Band Row', 'back', 'band', 'compound', 'beginner', '{"slug":"resistance-band-row","name":"Resistance Band Row","aliases":["Seated Band Row","Banded Row"],"muscle_group":"back","secondary":["lats","rear-delts","biceps"],"equipment":"band","mechanic":"compound","level":"beginner","summary":"A horizontal pull with a resistance band anchored in front of you. It trains the mid-back and lats and can be done anywhere you can anchor a band.","setup":["Anchor the band around a sturdy post, or sit on the floor and loop it around your feet.","Hold the ends with both hands and sit or stand tall with arms straight and the band tight.","Keep your knees slightly bent if seated, and your chest up."],"execution":["Pull your shoulder blades back and drive your elbows toward your hips.","Bring your hands to the sides of your lower ribs.","Squeeze your back for a moment at the end of the pull.","Return slowly until your arms are straight, without letting your shoulders round."],"cues":["Elbows to the hips","Chest tall","Squeeze the shoulder blades","Slow release"],"mistakes":["Leaning back to pull: keep your torso still and use a lighter band.","Shrugging the shoulders: keep them down and pull with the back.","Rounding forward on the return: sit tall and keep the chest up.","Unsafe anchor: check the band is secure and not frayed before pulling."],"default_sets":3,"default_reps":"12-15","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=lHuGxZZ09nY","title":"How to do Resistance Band Rows","author":"Cerin Rees","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=0wrB8VduUnM","title":"Banded Rows","author":"HealthFit Physical Therapy & Chiropractic Pasadena","checked":"2026-10-23"}]}'::jsonb),
('reverse-crunch', 'Reverse Crunch', 'abs', 'bodyweight', 'isolation', 'beginner', '{"slug":"reverse-crunch","name":"Reverse Crunch","aliases":["Hip Curl"],"muscle_group":"abs","secondary":[],"equipment":"bodyweight","mechanic":"isolation","level":"beginner","summary":"A floor ab exercise that curls the pelvis toward the ribs to train the lower abs.","setup":["Lie on your back with hips and knees bent to 90 degrees.","Place your arms by your sides or hold something behind your head.","Brace your abs."],"execution":["Curl your pelvis off the floor by drawing your knees toward your chest.","Lift your hips a few inches using your abs, not momentum.","Lower slowly until your tailbone touches the floor.","Do not swing the legs."],"cues":["Tuck the pelvis","Lift hips with the abs","Slow lower"],"mistakes":["Using momentum: slow down and pause at the top.","Pulling with arms: keep them relaxed.","Rolling onto the neck: keep the lift small.","Dropping the hips quickly: lower under control."],"default_sets":3,"default_reps":"10-15","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=XY8KzdDcMFg","title":"How To Do A Reverse Crunch","author":"PureGym","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=fhrkw1aaP8k","title":"Lower Ab Exercise Mistakes (REVERSE CRUNCH!)","author":"ATHLEAN-X™","checked":"2026-10-23"}]}'::jsonb),
('reverse-curl', 'Reverse Curl', 'forearms', 'barbell', 'isolation', 'beginner', '{"slug":"reverse-curl","name":"Reverse Curl","aliases":["Barbell Reverse Curl","Overhand Curl"],"muscle_group":"forearms","secondary":["biceps"],"equipment":"barbell","mechanic":"isolation","level":"beginner","summary":"A curl with an overhand grip that works the forearm muscles and the brachialis. Use lighter weights than with an underhand curl.","setup":["Hold a barbell or EZ bar with an overhand grip, hands about shoulder-width apart.","Stand tall with the bar at thigh level, elbows tucked to your sides.","Keep the wrists straight and the abs braced."],"execution":["Curl the bar toward your shoulders by bending the elbows while keeping the wrists in line.","Squeeze at the top without letting the wrists bend back.","Lower slowly to nearly straight arms.","Keep the torso still on every rep."],"cues":["Wrists neutral","Elbows at your sides","Light weight, slow reps"],"mistakes":["Letting the wrists collapse backward: use a lighter load and keep the knuckles in line with the forearms.","Swinging the body: slow the tempo and brace the core.","Elbows drifting forward: keep them pinned to the torso.","Using too heavy a bar: choose a weight you can control for all reps."],"default_sets":3,"default_reps":"10-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=Vepf9pZauCo","title":"How to do the Barbell Reverse Curl | 2 Minute Tutorials","author":"Jay Dunna ","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=didEQUuieRQ","title":"How To: Reverse Barbell Curl | BICEPS BUILDER","author":"ScottHermanFitness","checked":"2026-10-23"}]}'::jsonb),
('romanian-deadlift', 'Romanian Deadlift', 'hamstrings', 'barbell', 'compound', 'intermediate', '{"slug":"romanian-deadlift","name":"Romanian Deadlift","aliases":["RDL","Barbell Romanian Deadlift"],"muscle_group":"hamstrings","secondary":["glutes","lower-back"],"equipment":"barbell","mechanic":"compound","level":"intermediate","summary":"A hip-hinge lift that loads the hamstrings and glutes through a long range while the lower back works to hold a neutral spine. Useful for posterior-chain strength and hamstring size.","setup":["Stand holding the bar at hip height with an overhand grip just outside your thighs, taken from a rack or lifted from the floor.","Set your feet about hip width apart with a soft bend in the knees.","Pull your shoulders back and down, brace your trunk and keep your arms straight."],"execution":["Push your hips straight back while keeping the bar close to your legs.","Let the bar slide down your thighs with a flat back and a soft, fixed knee bend.","Lower until you feel a strong stretch in your hamstrings, usually around mid-shin, before your back begins to round.","Drive your hips forward and squeeze your glutes to stand tall.","Keep the bar in contact with your legs the whole way."],"cues":["Hips back, not down","Bar stays close","Flat back, soft knees","Squeeze the glutes at the top"],"mistakes":["Rounding the lower back: stop the descent earlier and brace harder before each rep.","Bending the knees too much so it turns into a squat: keep a fixed soft knee angle and send the hips back.","Bar drifting away from the legs: keep your lats tight and drag the bar along your thighs.","Leaning back at the top: finish by standing tall with the glutes, not by hyperextending the lower back."],"default_sets":3,"default_reps":"8-10","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=KTME4qWcvTM","title":"How to Do a Romanian Deadlift Correctly | Hamstrings Exercise Form Guide","author":"BACK2BASICS","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=osbkDJFMP-w","title":"How To Do A Barbell Romanian Deadlift (Correct Form)","author":"Feldkamp Performance Factory","checked":"2026-10-23"}]}'::jsonb),
('russian-twist', 'Russian Twist', 'abs', 'bodyweight', 'isolation', 'beginner', '{"slug":"russian-twist","name":"Russian Twist","aliases":["Seated Twist"],"muscle_group":"abs","secondary":[],"equipment":"bodyweight","mechanic":"isolation","level":"beginner","summary":"A seated rotation that trains the obliques and trunk. Start with bodyweight and add light weight only when your form is solid.","setup":["Sit on the floor with the knees bent and lean back to about 45 degrees with a straight spine.","Lift the feet slightly or keep them on the floor for an easier version.","Hold your hands together in front of the chest."],"execution":["Rotate the torso to one side, bringing the hands past the hip.","Return through the center and rotate to the other side.","Keep the chest tall and the movement slow and controlled.","Count each side as one rep."],"cues":["Rotate from the ribcage","Chest tall","Slow and controlled"],"mistakes":["Rounding the back: sit tall and reduce the lean.","Swinging only the arms: turn the shoulders and ribcage.","Rushing with momentum: slow down for control.","Using too much weight: add load only after the form is solid."],"default_sets":3,"default_reps":"10-20 per side","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=nhFynCkYtD4","title":"How to do the perfect Russian Twist and the most common mistakes","author":"Get Exercise Confident","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=IJDOoVyVjhc","title":"Russian Twist Tutorial - Proper Form and Technique","author":"Runna","checked":"2026-10-23"}]}'::jsonb),
('seated-cable-row', 'Seated Cable Row', 'back', 'cable', 'compound', 'beginner', '{"slug":"seated-cable-row","name":"Seated Cable Row","aliases":["Low Cable Row","Cable Row"],"muscle_group":"back","secondary":["lats","biceps","rear-delts","traps"],"equipment":"cable","mechanic":"compound","level":"beginner","summary":"A seated horizontal row on a low cable that gives constant tension on the mid back, lats and rear delts with low technical demand.","setup":["Attach a V-handle or close-grip handle to a low pulley and sit with the feet on the platform and knees slightly bent.","Lean forward to take the handle, then sit upright with a neutral spine and chest up.","Start with the arms extended and the shoulders set down."],"execution":["Pull the handle toward the lower ribs, driving the elbows back along the body.","Squeeze the shoulder blades together at the end.","Let the handle return slowly, stretching the arms forward.","Keep the torso upright throughout."],"cues":["Chest tall","Elbows past the ribs","Slow stretch forward"],"mistakes":["Rocking back and forth: lighten the weight and keep the torso nearly still.","Shrugging the shoulders: keep them down as you pull.","Rounding the back at the stretch: only reach forward as far as the spine stays neutral.","Pulling with the hands: think elbows to the hips."],"default_sets":3,"default_reps":"8-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=XaHV_8Nbyug","title":"Seated Close Grip Cable Row (Exercise Tutorial + Form Tips) | Team Evolve","author":"Vivian Ngo","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=f_r95UajQcg","title":"How to Do a Seated Cable Row","author":"REP","checked":"2026-10-23"}]}'::jsonb),
('seated-calf-raise', 'Seated Calf Raise', 'calves', 'machine', 'isolation', 'beginner', '{"slug":"seated-calf-raise","name":"Seated Calf Raise","aliases":["Machine Seated Calf Raise"],"muscle_group":"calves","secondary":[],"equipment":"machine","mechanic":"isolation","level":"beginner","summary":"A calf isolation exercise performed seated with the knees bent, which shifts the emphasis to the soleus muscle underneath the calf.","setup":["Sit on the machine and place the balls of your feet on the platform with your heels hanging off.","Set the knee pad snugly over your lower thighs.","Position your feet about hip width apart and release the safety catch."],"execution":["Lower your heels slowly until you feel a full stretch in your calves.","Pause briefly at the bottom.","Press up through the balls of your feet as high as possible.","Squeeze your calves at the top for a second.","Lower under control and repeat, then re-engage the safety."],"cues":["Full stretch, full squeeze","Pause at the bottom","No bouncing"],"mistakes":["Bouncing at the bottom: pause for a second and keep a steady tempo.","Using a partial range: go through the full range every rep.","Rolling the ankles out: keep the load through the ball of the big toe.","Using too heavy a load: reduce the weight until you can control the full range."],"default_sets":3,"default_reps":"12-15","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=6O5hh1rBtx8","title":"How to PROPERLY Calf Raise (SEATED CALF RAISE TIPS)","author":"Colossus Fitness","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=I1uQtobaNRQ","title":"Seated Calf Raise | Proper Form Tutorial for Stronger Calves","author":"FIT.nl","checked":"2026-10-23"}]}'::jsonb),
('seated-dumbbell-lateral-raise', 'Seated Dumbbell Lateral Raise', 'shoulders', 'dumbbell', 'isolation', 'beginner', '{"slug":"seated-dumbbell-lateral-raise","name":"Seated Dumbbell Lateral Raise","aliases":["Seated Side Raise"],"muscle_group":"shoulders","secondary":[],"equipment":"dumbbell","mechanic":"isolation","level":"beginner","summary":"A lateral raise performed seated to remove leg drive and body swing, keeping the focus on the side delts.","setup":["Sit on a bench with a light dumbbell in each hand at your sides.","Sit tall or lean slightly forward with the core braced.","Keep a slight bend in the elbows.","Pull shoulders back and down."],"execution":["Raise the dumbbells out to the sides until about shoulder height.","Lead with the elbows.","Pause at the top and lower slowly.","Keep the torso still."],"cues":["Elbows lead","No swinging","Stop at shoulder height"],"mistakes":["Using momentum by rocking: choose a lighter weight.","Shrugging: keep shoulders depressed.","Raising too high: stop around shoulder height.","Rushing the lowering: take 2-3 seconds."],"default_sets":3,"default_reps":"12-20","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=Pq1MY5lz4Jo","title":"Seated Dumbbell Lateral Raise | Proper Form & Technique","author":"Conditioned by Kelly Tekin","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=OsDslPhkUWo","title":"How to Do Seated Dumbbell Lateral Raises for Bigger, Wider Shoulders","author":"HW Motivation","checked":"2026-10-23"}]}'::jsonb),
('seated-dumbbell-shoulder-press', 'Seated Dumbbell Shoulder Press', 'shoulders', 'dumbbell', 'compound', 'beginner', '{"slug":"seated-dumbbell-shoulder-press","name":"Seated Dumbbell Shoulder Press","aliases":["Dumbbell Shoulder Press","Seated DB Press"],"muscle_group":"shoulders","secondary":["triceps"],"equipment":"dumbbell","mechanic":"compound","level":"beginner","summary":"A seated overhead press with dumbbells that trains the shoulders and triceps with back support for stability.","setup":["Set the bench back to a near-upright angle and sit with back and glutes against the pad.","Lift the dumbbells to shoulder height, palms forward or slightly angled.","Plant feet firmly and brace the abs.","Keep forearms near vertical under the dumbbells."],"execution":["Press the dumbbells overhead until the arms are nearly straight.","Let them come slightly toward each other at the top without clanking.","Lower under control until the upper arms are about parallel to the floor.","Repeat without arching the back."],"cues":["Forearms vertical","Ribs down","Drive up and slightly in"],"mistakes":["Back arching off the pad: keep the lower back supported and lower the weight.","Elbows flared far behind the body: keep them slightly in front of the shoulders.","Shrugging up: keep the shoulders down until the arms extend.","Partial range of motion: lower to about ear level."],"default_sets":3,"default_reps":"8-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=SSXS4Z8OkCg","title":"Seated Dumbbell Shoulder Press: Demonstration","author":"StrengthLog","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=JvOJ3IW5JoA","title":"Seated Dumbbell Shoulder Press Technique and Spotting Tutorial","author":"Josh Hauptman","checked":"2026-10-23"}]}'::jsonb),
('seated-leg-curl', 'Seated Leg Curl', 'hamstrings', 'machine', 'isolation', 'beginner', '{"slug":"seated-leg-curl","name":"Seated Leg Curl","aliases":["Seated Hamstring Curl","Machine Leg Curl"],"muscle_group":"hamstrings","secondary":["calves"],"equipment":"machine","mechanic":"isolation","level":"beginner","summary":"A machine curl performed seated, which keeps the hips stable and loads the hamstrings with the hips flexed.","setup":["Adjust the seat and back pad so your knees line up with the machine''s pivot.","Place the ankle pad just above your heels and lower the thigh pad securely across your thighs.","Sit upright with your back supported and hold the handles."],"execution":["Curl your heels down and back by bending your knees as far as you can control.","Squeeze your hamstrings at the bottom of the rep.","Return slowly over two to three seconds until your legs are almost straight.","Keep your back against the pad and your thighs pressed down.","Repeat for the set."],"cues":["Heels down and back","Thighs pinned under the pad","Slow return"],"mistakes":["Lifting the hips or leaning back to cheat: keep the thigh pad snug and your back on the pad.","Letting the weight stack drop on the return: control the weight up slowly.","Cutting the range short: use the full range you can control.","Using a weight that is too heavy: reduce the load until you can control both directions."],"default_sets":3,"default_reps":"10-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=_2Kd0d-JEUM","title":"How to do a Seated Leg Curl  | Proper Form & Technique | NASM","author":"National Academy of Sports Medicine (NASM)","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=jq03iefZxjc","title":"How to Do a Seated Leg Curl | Exercise with PartnerMD","author":"PartnerMD","checked":"2026-10-23"}]}'::jsonb),
('side-plank', 'Side Plank', 'abs', 'bodyweight', 'isolation', 'beginner', '{"slug":"side-plank","name":"Side Plank","aliases":["Lateral Plank"],"muscle_group":"abs","secondary":["shoulders"],"equipment":"bodyweight","mechanic":"isolation","level":"beginner","summary":"A side-lying hold that trains the obliques and the muscles on the side of the trunk and hip, improving lateral stability.","setup":["Lie on your side with the elbow directly under the shoulder and the legs stacked.","Place the top hand on the hip or extend it up.","Brace your abs before you lift."],"execution":["Lift the hips so the body forms a straight line from head to feet.","Keep the hips stacked and the neck neutral.","Hold while breathing steadily.","Lower under control and repeat on the other side."],"cues":["Elbow under shoulder","Hips high","Straight line"],"mistakes":["Letting the hips sag: squeeze the glutes and lift the hips.","Rolling forward or back: keep the shoulders and hips stacked.","Elbow in front of or behind the shoulder: place it directly under.","Holding too long with poor form: shorten the hold or bend the knees."],"default_sets":3,"default_reps":"20-40 s each side","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=N_s9em1xTqU","title":"Core Exercise: Side Plank","author":"Children''s Hospital Colorado","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=NXr4Fw8q60o","title":"How to Do a Side Plank | Ab Workout","author":"Howcast","checked":"2026-10-23"}]}'::jsonb),
('single-leg-dumbbell-calf-raise', 'Single-Leg Dumbbell Calf Raise', 'calves', 'dumbbell', 'isolation', 'beginner', '{"slug":"single-leg-dumbbell-calf-raise","name":"Single-Leg Dumbbell Calf Raise","aliases":["One-Leg Dumbbell Calf Raise"],"muscle_group":"calves","secondary":[],"equipment":"dumbbell","mechanic":"isolation","level":"beginner","summary":"A single-leg calf raise with a dumbbell, done on a step to work through a full range. It needs only a dumbbell and a step and trains each calf separately.","setup":["Stand on a step or platform with the ball of one foot on the edge and the heel hanging off.","Hold a dumbbell in the hand on the same side as the working leg.","Hold on to a wall or rail with the other hand for balance.","Cross the other foot behind or let it hang."],"execution":["Lower your heel slowly below the step until you feel a calf stretch.","Pause briefly at the bottom.","Rise as high as you can onto the ball of your foot.","Squeeze at the top for a second.","Complete all reps on one side, then switch legs."],"cues":["Stretch at the bottom","Squeeze at the top","Slow and steady"],"mistakes":["Rushing and bouncing: slow down and pause at the bottom.","Cutting the range short: use the full range.","Losing balance: hold a rail for support.","Rolling the ankle outward: keep the ball of the foot centered."],"default_sets":3,"default_reps":"12-15 per leg","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=1D7s-VyLq0Y","title":"How To Do a Single Leg Dumbbell Calf Raise","author":"Precision Nutrition","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=KcTEGifMTDY","title":"Dumbbell Single Leg Standing Calf Raise","author":"OPEX Fitness","checked":"2026-10-23"}]}'::jsonb),
('single-leg-glute-bridge', 'Single-Leg Glute Bridge', 'glutes', 'bodyweight', 'compound', 'intermediate', '{"slug":"single-leg-glute-bridge","name":"Single-Leg Glute Bridge","aliases":["Single Leg Hip Bridge","One-Leg Glute Bridge"],"muscle_group":"glutes","secondary":["hamstrings","abs"],"equipment":"bodyweight","mechanic":"compound","level":"intermediate","summary":"A harder glute bridge on one leg that trains the glutes and hip stability. Do the two-leg bridge first if you are new.","setup":["Lie on your back with knees bent and feet flat, hip width apart.","Lift one leg and hold the knee bent over your hips or the leg extended in line with the other thigh.","Brace your abs and keep your arms by your sides."],"execution":["Press through the heel of the grounded foot and lift your hips.","Squeeze your glute at the top until your body forms a line from shoulder to knee.","Keep your hips level and do not let the free side drop.","Lower under control and repeat, then switch legs."],"cues":["Drive through the heel","Hips level","Ribs down"],"mistakes":["Arching the lower back: tuck the pelvis and stop when the body is in a straight line.","Hips rotating or dropping to one side: brace the abs and use a smaller range.","Pushing off the toes: keep the heel planted and the foot flat.","Struggling to hold form: go back to two-leg bridges."],"default_sets":3,"default_reps":"8-15 per leg","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=V1NKta2znwU","title":"Single-leg Bodyweight Glute Bridge","author":"Girls Gone Strong | Women''s Health & Fitness","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=b1zTCyGJXCQ","title":"Single Leg Glute Bridge Exercise | How To Perform And Common Mistakes","author":"Dr. Carl Baird","checked":"2026-10-23"}]}'::jsonb),
('standing-calf-raise', 'Standing Calf Raise', 'calves', 'machine', 'isolation', 'beginner', '{"slug":"standing-calf-raise","name":"Standing Calf Raise","aliases":["Machine Standing Calf Raise","Calf Raise"],"muscle_group":"calves","secondary":[],"equipment":"machine","mechanic":"isolation","level":"beginner","summary":"An isolation lift for the calf muscles performed standing, with the knees nearly straight, which loads the gastrocnemius in particular.","setup":["Set the shoulder pads so you can stand upright with the balls of your feet on the platform and heels hanging off.","Position your feet about hip width apart with toes pointing forward.","Keep your knees nearly straight, but not locked, and brace your trunk."],"execution":["Lower your heels as far as you comfortably can to get a full stretch in your calves.","Pause briefly at the bottom.","Rise as high as possible onto the balls of your feet, squeezing your calves at the top.","Hold the top for a second, then lower slowly.","Repeat without bouncing."],"cues":["Full stretch at the bottom","Pause at the top","Slow and controlled"],"mistakes":["Bouncing out of the bottom: pause and use a controlled tempo.","Cutting the range short: go to a full stretch and a full squeeze.","Bending the knees to cheat: keep them almost straight.","Rolling the ankles outward or inward: press through the ball of the big toe and keep the foot straight."],"default_sets":3,"default_reps":"10-15","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=SVtg-1loH4c","title":"How to PROPERLY Standing Calf Raise | Tips & Common Mistakes","author":"Colossus Fitness","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=k8ipHzKeAkQ","title":"Exercises with an Athletic Trainer: Standing Calf Raises","author":"Children''s Hospital Colorado","checked":"2026-10-23"}]}'::jsonb),
('straight-arm-pulldown', 'Straight-Arm Pulldown', 'lats', 'cable', 'isolation', 'beginner', '{"slug":"straight-arm-pulldown","name":"Straight-Arm Pulldown","aliases":["Cable Straight-Arm Pulldown","Lat Prayer"],"muscle_group":"lats","secondary":["triceps","rear-delts","abs"],"equipment":"cable","mechanic":"isolation","level":"beginner","summary":"A cable pull with the arms nearly straight that isolates the lats through shoulder extension with little biceps involvement.","setup":["Set a cable at about head height with a straight bar or rope.","Step back, hinge slightly at the hips and hold the bar with arms extended in front of you and a soft bend in the elbows.","Brace the abs and keep the ribs down."],"execution":["Pull the bar in an arc down to the thighs, keeping the elbows slightly bent and fixed.","Squeeze the lats at the bottom.","Let the bar rise slowly until your arms are at about shoulder height or until you feel a full lat stretch.","Keep the torso still."],"cues":["Sweep the bar down like a big arc","Elbows locked at one angle","Squeeze the armpits"],"mistakes":["Bending and extending the elbows like a triceps pushdown: fix the elbow angle.","Swinging the torso: lower the weight and brace the abs.","Letting the shoulders roll forward: keep the chest up and shoulders down.","Cutting the stretch short: allow the bar to rise until the lats are lengthened."],"default_sets":3,"default_reps":"10-15","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=duHQk2PxNos","title":"Cable Straight Arm Pulldown - Proper Form & Technique [4K]","author":"Steev","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=hAMcfubonDc","title":"The Perfect Straight Arm Pulldown","author":"Andrew Kwong (DeltaBolic)","checked":"2026-10-23"}]}'::jsonb),
('superman', 'Superman', 'lower-back', 'bodyweight', 'isolation', 'beginner', '{"slug":"superman","name":"Superman","aliases":["Superman Hold","Back Extension on Floor"],"muscle_group":"lower-back","secondary":["glutes","hamstrings"],"equipment":"bodyweight","mechanic":"isolation","level":"beginner","summary":"A floor exercise that trains the lower back, glutes and back muscles without equipment.","setup":["Lie face down on a mat with your arms extended in front and legs straight.","Rest your forehead on the floor so your neck is neutral.","Gently brace your abs and squeeze your glutes."],"execution":["Lift your arms, chest and legs a few inches off the floor at the same time.","Keep your gaze down so the neck stays in line with the spine.","Hold for one to two seconds without arching hard.","Lower under control."],"cues":["Long, not high","Glutes tight","Neck neutral"],"mistakes":["Lifting too high and compressing the lower back: lift only a few inches.","Cranking the head up: keep the gaze down at the floor.","Holding the breath: breathe steadily.","Pain in the back: stop and choose a lighter version, such as lifting one arm and the opposite leg."],"default_sets":3,"default_reps":"10-15","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=J9zXkxUAfUA","title":"Core Exercise: Superman","author":"Children''s Hospital Colorado","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=jTNpZIl1qU0","title":"Proper Back Extension and Superman Form! -MoveU","author":"MoveU","checked":"2026-10-23"}]}'::jsonb),
('t-bar-row', 'T-Bar Row', 'back', 'barbell', 'compound', 'intermediate', '{"slug":"t-bar-row","name":"T-Bar Row","aliases":["Landmine Row"],"muscle_group":"back","secondary":["lats","traps","biceps","rear-delts","lower-back"],"equipment":"barbell","mechanic":"compound","level":"intermediate","summary":"A heavy row using a barbell anchored at one end or a T-bar machine, with a close neutral grip that loads the mid back and lats.","setup":["Anchor one end of the barbell in a corner or landmine and load the other end.","Straddle the bar, hinge at the hips with a flat back and grip the handle or the bar under the plates.","Stand the weight up, brace and keep the knees slightly bent."],"execution":["Pull the weight toward the lower chest, driving the elbows back.","Squeeze the shoulder blades together at the top.","Lower under control until the arms are straight.","Hold the same torso angle on every rep."],"cues":["Proud chest","Elbows back","Keep hips low and still"],"mistakes":["Jerking with the hips: lighten the load and keep the torso angle fixed.","Rounding the lower back: hinge from the hips and brace.","Cutting reps short: lower until the arms are fully straight.","Shrugging toward the ears: keep the shoulders down and pull with the elbows."],"default_sets":3,"default_reps":"8-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=zAZQJYx9vrk","title":"T-Bar Row Exercise | Proper Form, Muscles Worked & Common Mistakes","author":"Adam Skoda","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=hYo72r8Ivso","title":"How To Do T Bar Rows (Landmine Rows)","author":"PureGym","checked":"2026-10-23"}]}'::jsonb),
('triceps-rope-pushdown', 'Triceps Rope Pushdown', 'triceps', 'cable', 'isolation', 'beginner', '{"slug":"triceps-rope-pushdown","name":"Triceps Rope Pushdown","aliases":["Rope Pushdown","Cable Triceps Pushdown"],"muscle_group":"triceps","secondary":[],"equipment":"cable","mechanic":"isolation","level":"beginner","summary":"A cable isolation exercise for the triceps that allows a full contraction by spreading the rope at the bottom.","setup":["Attach a rope to a high pulley and stand close to the stack.","Grip the rope with neutral palms, elbows tucked against your sides.","Lean very slightly forward with a braced core.","Start with elbows bent at about 90 degrees."],"execution":["Extend the elbows to push the rope down toward your thighs.","At the bottom, spread the rope ends apart and squeeze the triceps.","Return slowly until the forearms are about parallel to the floor.","Keep your upper arms still throughout."],"cues":["Elbows glued to the ribs","Spread the rope at the bottom","Slow on the way up"],"mistakes":["Elbows drifting forward: pin them to the sides.","Leaning over the stack with body weight: stand tall and reduce load.","Letting the weight stack slam: keep tension through the top.","Using the shoulders to push: keep shoulders down and still."],"default_sets":3,"default_reps":"10-15","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=vPeQu_L-1n0","title":"How to Do Tricep Pushdowns with a Rope (Step-by-Step Breakdown)","author":"REP","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=NIodhHkli2Y","title":"Rope Triceps Pushdown - HASfit Triceps Exercise Demonstration - Rope Push Downs - Cable Rope","author":"HASfit","checked":"2026-10-23"}]}'::jsonb),
('wall-sit', 'Wall Sit', 'quads', 'bodyweight', 'isolation', 'beginner', '{"slug":"wall-sit","name":"Wall Sit","aliases":["Wall Squat Hold","Isometric Wall Squat"],"muscle_group":"quads","secondary":["glutes","calves"],"equipment":"bodyweight","mechanic":"isolation","level":"beginner","summary":"An isometric leg hold against a wall that builds muscular endurance in the thighs without equipment.","setup":["Stand with your back flat against a wall and feet about shoulder width apart.","Walk your feet forward about two feet from the wall.","Slide your back down the wall."],"execution":["Lower until your thighs are about parallel to the floor, or higher if that is too hard.","Keep your knees above your ankles and your back flat on the wall.","Rest your hands on your thighs or hold them in front, not on your knees.","Breathe steadily and hold for the time, then slide up the wall."],"cues":["Back flat on the wall","Knees over ankles","Breathe"],"mistakes":["Knees in front of the toes: walk the feet farther from the wall.","Sitting too high or too low to hold: pick a depth you can hold with good form.","Pushing with the hands on the knees: rest hands on thighs or in front of you.","Holding your breath: breathe slowly throughout."],"default_sets":3,"default_reps":"30-45 s","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=cWTZ8Am1Ee0","title":"How to Do a Wall Sit Exercise | 30 Seconds | MedBridge","author":"Medbridge","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=eb7vLD6V-iU","title":"How To Do A Wall Sit | Chelmsford Physio","author":"Chelmsford Physio","checked":"2026-10-23"}]}'::jsonb),
('wide-grip-lat-pulldown', 'Wide-Grip Lat Pulldown', 'lats', 'cable', 'compound', 'beginner', '{"slug":"wide-grip-lat-pulldown","name":"Wide-Grip Lat Pulldown","aliases":["Lat Pulldown","Wide Pulldown"],"muscle_group":"lats","secondary":["biceps","back","rear-delts"],"equipment":"cable","mechanic":"compound","level":"beginner","summary":"A cable pulldown with a wide overhand grip that trains the lats and upper back. A scalable alternative to pull-ups.","setup":["Adjust the thigh pad so your legs are snug and you cannot lift off the seat.","Grip the bar with an overhand grip just outside shoulder width.","Sit tall, lean back slightly, and let the arms extend with the shoulders set down."],"execution":["Pull the shoulder blades down first.","Drive the elbows down and slightly back, bringing the bar to the upper chest.","Squeeze briefly at the bottom.","Let the bar rise under control until the arms are straight."],"cues":["Elbows to the pockets","Chest up to meet the bar","Do not yank with momentum"],"mistakes":["Pulling the bar behind the neck: bring it to the upper chest in front.","Leaning far back and swinging: reduce the weight and keep a slight, fixed lean.","Letting the weight pull the shoulders up at the top: control the return and keep the lats engaged.","Grip too wide to feel the lats: use just outside shoulder width."],"default_sets":3,"default_reps":"8-12","references":[{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=RTNmVfnRitA","title":"How to Do Lat Pulldowns Correctly","author":"Physical Therapy First","checked":"2026-10-23"},{"type":"video","platform":"youtube","url":"https://www.youtube.com/watch?v=CAwf7n6Luuc","title":"How To: Lat Pulldown | 3 GOLDEN RULES","author":"ScottHermanFitness","checked":"2026-10-23"}]}'::jsonb)
